/**
 * Where everything on the Restaurant Arena floor goes, for a canvas of any
 * size.
 *
 * The scene itself is authored in CSS-pixel units and repaints from scratch on
 * every state change (see `restaurant-arena-scene.ts`), so the whole layout is
 * a pure function of the canvas box: one call per paint, no retained state.
 * Keeping it out of the scene is what makes the sizing behaviour — the
 * responsive band-squeeze below, the compact break, the `scale` ramp — testable
 * without booting Phaser.
 *
 * Two things this file is responsible for beyond "which rectangle goes where":
 *
 *  - `scale`. A window twice the baseline size drawn with baseline-sized type
 *    reads as a big empty room with unreadable labels in it. Every font size
 *    and figure in the scene is multiplied by this, so text grows with the
 *    window instead of staying pinned to a 520×740 design. It never goes below
 *    1: shrinking type is how you make a small window illegible, so a small
 *    window gets the compact layout instead (fewer/tighter bands, same
 *    readable type).
 *  - `spineY`. The hallway. Staff walking between rooms ride this line rather
 *    than cutting diagonally across the dining room (see `staff-walk.ts`), so
 *    it has to be a y that is inside the kitchen, the pass *and* the dining
 *    room — the three rooms the corridor connects.
 */

export type ArenaRect = { x: number; y: number; width: number; height: number };
export type ArenaPoint = { x: number; y: number };
export type ArenaLocation = "floor" | "kitchen" | "pass" | "queue";

export interface RestaurantArenaLayout {
  compact: boolean;
  scale: number;
  feedBeside: boolean;
  topBar: ArenaRect;
  brief: ArenaRect;
  kitchen: ArenaRect;
  pass: ArenaRect;
  dining: ArenaRect;
  door: ArenaRect;
  doorStand: ArenaRect;
  waypoints: Record<ArenaLocation, ArenaPoint>;
  /** Y coordinate of the hallway line that runs through the pass zone. */
  spineY: number;
  tickets: ArenaRect;
  feed: ArenaRect;
}

/** The window this scene was designed against: `scale` is exactly 1 here. */
export const BASELINE_WIDTH = 520;
export const BASELINE_HEIGHT = 740;
/**
 * Past roughly 1.9× the design size the room is big enough that growing the
 * type further just wastes the space it was supposed to fill.
 */
export const MAX_SCALE = 1.9;
/** Under this, bands tighten and the growing-text ramp is switched off. */
export const COMPACT_WIDTH = 460;
export const COMPACT_HEIGHT = 420;
/** The feed only earns a side rail once the floor can spare the width. */
export const FEED_BESIDE_WIDTH = 600;

/** The host stand is a thing you aim a drag at, so it has a floor size. */
export const MIN_DOOR_STAND_WIDTH = 56;
export const MIN_DOOR_STAND_HEIGHT = 22;

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

function center(rect: ArenaRect): ArenaPoint {
  return { x: Math.round(rect.x + rect.width / 2), y: Math.round(rect.y + rect.height / 2) };
}

/**
 * How much bigger than the baseline this window is, in the *tighter* of the two
 * axes — a window that is wide but short has no more room for tall type than a
 * short one, so the smaller ratio wins.
 */
export function arenaScale(width: number, height: number): number {
  if (width < COMPACT_WIDTH || height < COMPACT_HEIGHT) return 1;
  const ratio = Math.min(width / BASELINE_WIDTH, height / BASELINE_HEIGHT);
  return clamp(ratio, 1, MAX_SCALE);
}

export function restaurantArenaLayout(width: number, height: number): RestaurantArenaLayout {
  const w = Math.max(0, Math.round(width));
  const h = Math.max(0, Math.round(height));
  const compact = w < COMPACT_WIDTH || h < COMPACT_HEIGHT;
  const scale = arenaScale(w, h);
  const feedBeside = w >= FEED_BESIDE_WIDTH;
  /** A baseline design length, at this window's size. */
  const unit = (px: number) => Math.round(px * scale);

  const margin = Math.min(compact ? 6 : unit(8), Math.floor(Math.min(w, h) / 20));
  const contentWidth = Math.max(0, w - margin * 2);
  const innerHeight = Math.max(0, h - margin * 2);
  // Gaps are capped against the box as well, so a silly-small canvas spends
  // its pixels on rooms rather than on the spaces between them.
  const gapX = Math.min(compact ? 4 : unit(6), Math.floor(contentWidth / 6));
  const gapY = Math.min(compact ? 4 : unit(6), Math.floor(innerHeight / 12));

  // ── Vertical bands ────────────────────────────────────────────────────
  // topBar / brief / floor / tickets, plus the feed as a fourth band when it
  // isn't beside the floor. The floor gets whatever is left; if that would
  // leave it unusably short, the fixed bands are squeezed proportionally
  // instead of the floor going negative and spilling out of the canvas.
  const bandGaps = gapY * (feedBeside ? 3 : 4);
  const room = Math.max(0, innerHeight - bandGaps);
  const wanted = {
    topBar: compact ? 32 : unit(38),
    brief: compact ? 28 : unit(32),
    tickets: compact ? 60 : unit(72),
    feed: feedBeside ? 0 : Math.max(compact ? 90 : unit(110), Math.round(h * 0.2)),
  };
  const wantedSum = wanted.topBar + wanted.brief + wanted.tickets + wanted.feed;
  const floorWanted = compact ? 90 : unit(120);
  let squeeze = 1;
  let floorHeight = room - wantedSum;
  if (floorHeight < floorWanted) {
    // The floor is the game; it keeps 40% of the body no matter how cramped
    // the window is, and the chrome around it gives up the difference.
    floorHeight = Math.min(floorWanted, Math.round(room * 0.4));
    squeeze = wantedSum > 0 ? Math.max(0, room - floorHeight) / wantedSum : 0;
  }
  const topBarHeight = Math.floor(wanted.topBar * squeeze);
  const briefHeight = Math.floor(wanted.brief * squeeze);
  const ticketsHeight = Math.floor(wanted.tickets * squeeze);
  const feedHeight = Math.floor(wanted.feed * squeeze);

  const briefY = margin + topBarHeight + gapY;
  const bodyY = briefY + briefHeight + gapY;

  // ── The floor column, and the feed's side rail ────────────────────────
  const feedWidth = feedBeside
    ? clamp(Math.round(contentWidth * 0.26), Math.min(unit(200), Math.round(contentWidth * 0.42)), Math.round(contentWidth * 0.42))
    : 0;
  const columnWidth = feedBeside ? Math.max(0, contentWidth - feedWidth - gapX) : contentWidth;

  // kitchen | pass | dining, left to right, with the two gaps taken out of
  // the row up front so the three rooms always add back up to the column.
  const rowWidth = Math.max(0, columnWidth - gapX * 2);
  const kitchenWidth = Math.round(rowWidth * 0.25);
  const passWidth = clamp(Math.max(unit(24), Math.round(rowWidth * 0.075)), 0, Math.round(rowWidth * 0.2));
  const diningWidth = Math.max(0, rowWidth - kitchenWidth - passWidth);

  const doorHeight = clamp(
    Math.max(unit(56), Math.round(floorHeight * 0.32)),
    0,
    Math.max(0, floorHeight - gapY - Math.min(unit(60), Math.round(floorHeight * 0.3))),
  );
  const diningHeight = Math.max(0, floorHeight - doorHeight - gapY);

  const kitchen: ArenaRect = { x: margin, y: bodyY, width: kitchenWidth, height: floorHeight };
  const pass: ArenaRect = { x: kitchen.x + kitchenWidth + gapX, y: bodyY, width: passWidth, height: floorHeight };
  const diningX = pass.x + passWidth + gapX;
  const dining: ArenaRect = { x: diningX, y: bodyY, width: diningWidth, height: diningHeight };
  const door: ArenaRect = {
    x: diningX,
    y: bodyY + diningHeight + gapY,
    width: diningWidth,
    height: doorHeight,
  };

  // The host stand. It is a drop target for a dragged host as much as it is a
  // panel, so it keeps a usable size even when the door band is tiny — and is
  // then clamped into the canvas rather than into the door.
  const labelHeight = unit(14);
  const standWidth = Math.max(MIN_DOOR_STAND_WIDTH, Math.min(unit(90), Math.round(door.width * 0.36)));
  const standHeight = Math.max(MIN_DOOR_STAND_HEIGHT, Math.min(unit(36), door.height - labelHeight - 4));
  const hostGutter = Math.min(unit(40), Math.max(0, door.width - standWidth - 4));
  const doorStand: ArenaRect = {
    x: clamp(door.x + hostGutter, 0, Math.max(0, w - standWidth)),
    y: clamp(door.y + labelHeight, 0, Math.max(0, h - standHeight)),
    width: standWidth,
    height: standHeight,
  };

  // The hallway. Lands inside the dining room, the pass and the kitchen at
  // once, which is what lets a walk between any two of them ride it.
  const spineY = Math.round(dining.y + dining.height / 2);

  const waypoints: Record<ArenaLocation, ArenaPoint> = {
    kitchen: center(kitchen),
    pass: center(pass),
    floor: center(dining),
    queue: center(doorStand),
  };

  const tickets: ArenaRect = {
    x: margin,
    y: bodyY + floorHeight + gapY,
    width: columnWidth,
    height: ticketsHeight,
  };
  const feed: ArenaRect = feedBeside
    ? {
        x: margin + columnWidth + gapX,
        y: bodyY,
        width: feedWidth,
        height: floorHeight + gapY + ticketsHeight,
      }
    : {
        x: margin,
        y: tickets.y + ticketsHeight + gapY,
        width: contentWidth,
        height: feedHeight,
      };

  return {
    compact,
    scale,
    feedBeside,
    topBar: { x: margin, y: margin, width: contentWidth, height: topBarHeight },
    brief: { x: margin, y: briefY, width: contentWidth, height: briefHeight },
    kitchen,
    pass,
    dining,
    door,
    doorStand,
    waypoints,
    spineY,
    tickets,
    feed,
  };
}

