/**
 * `layout.scale` for the paint in progress — 1 at the design size, up to
 * ~1.9 on a big window (see `restaurant-arena-layout.ts`). Type sizes and
 * figure sizes are authored against the design size and multiplied by this,
 * which is what keeps a label readable on a 1440p window instead of turning
 * into a 6px smudge in the corner of a room four times the size it was drawn
 * for.
 */
private uiScale = 1;

/** Rounds a design size into the pixel string Phaser wants. */
private fs(px: number): string {
  return `${Math.max(5, Math.round(px * this.uiScale))}px`;
}

/** A design length in this paint's units. */
private px(length: number): number {
  return length * this.uiScale;
}

