private stackedSlot(location: Location, offset: number, layout: RestaurantArenaLayout): ArenaPoint {
  const compact = layout.compact;
  const slot = layout.waypoints[location];
  return { x: slot.x + offset * (compact ? 17 : this.px(22)), y: slot.y };
}

private drawWorkers(layout: RestaurantArenaLayout): void {
  const compact = layout.compact;
  const offsets = new Map<Location, number>();
  this.staffTokens.clear();

  for (const worker of this.state.workers) {
    const location = this.visualLocation(worker);
    const offset = offsets.get(location) ?? 0;
    offsets.set(location, offset + 1);
    const slot = this.stackedSlot(location, offset, layout);
    // The walker owns the pixel position; the slot is only where it is
    // *heading*. A repaint mid-walk (or mid-drag) therefore rebuilds the
    // token where the person currently is, not back at their station.
    const walker = this.walker(worker.role, location, slot);
    if (walker.node !== location || (!walker.walking && !walker.dragging && this.awayFrom(walker, slot))) {
      walker.setTarget(location, this.slotWaypoints(layout, location, slot), layout.spineY);
    }

    const token = this.buildAvatar(walker.x, walker.y, worker.role, worker.load, compact);
    this.staffTokens.set(worker.role, token);
    const heldHost = worker.role === "host" && Boolean(this.state.seatingHeld) && location === "queue";
    const status = heldHost ? "acting" : (this.workerStatuses.get(worker.role) ?? this.workerStatus(worker));
    this.drawWorkerBadge(token, status, compact, heldHost);
    this.drawSpeechBubble(token, worker.role, compact);
    this.makeDraggable(token, worker.role, location, layout);
  }
}

private walker(role: Role, location: Location, slot: ArenaPoint): StaffWalker {
  const existing = this.walkers.get(role);
  if (existing) return existing;
  const walker = new StaffWalker(location, slot);
  this.walkers.set(role, walker);
  return walker;
}

private awayFrom(walker: StaffWalker, slot: ArenaPoint): boolean {
  return Math.hypot(walker.x - slot.x, walker.y - slot.y) > 1;
}

/**
 * The walk graph's waypoints, with this walker's own stacked slot standing in
 * for the destination — two cooks in the same kitchen shouldn't finish their
 * walks standing inside each other.
 */
private slotWaypoints(
  layout: RestaurantArenaLayout,
  location: Location,
  slot: ArenaPoint,
): Record<Location, ArenaPoint> {
  return { ...layout.waypoints, [location]: slot };
}

/**
 * Drag a member of staff onto another zone to reassign them — the same
 * `assign_<role>_<location>` action the keyboard and the agents use, except
 * you point at where you want them.
 *
 * Dropping is the only part that talks to the game. Everything before it is
 * local: the token follows the pointer, the zone under it lights up, and any
 * repaint the shift asks for in the meantime is held by the gate so the thing
 * being dragged is still there to be dropped.
 */
private makeDraggable(
  token: Phaser.GameObjects.Container,
  role: Role,
  from: Location,
  layout: RestaurantArenaLayout,
): void {
  const reach = this.px(compactReach(layout.compact));
  token.setInteractive(
    new Phaser.Geom.Rectangle(-reach / 2, -reach * 0.85, reach, reach * 1.5),
    Phaser.Geom.Rectangle.Contains,
    { draggable: true, useHandCursor: true },
  );
  this.input.setDraggable(token);

  const halo = this.add.rectangle(0, 0, 0, 0).setOrigin(0, 0).setDepth(19).setVisible(false);
  halo.setStrokeStyle(2, COLORS.pass, 0.95);

  token.on("dragstart", () => {
    this.repaintGate.beginDrag();
    this.draggingRole = role;
    const walker = this.walkers.get(role);
    if (walker) walker.dragging = true;
    // The idle bob is a tween on this container's y; it would fight the
    // pointer for the token.
    this.tweens.killTweensOf(token);
    token.setDepth(40);
    token.setAlpha(0.92);
  });

  token.on("drag", (_pointer: Phaser.Input.Pointer, dragX: number, dragY: number) => {
    token.setPosition(dragX, dragY);
    const walker = this.walkers.get(role);
    if (walker) {
      walker.x = dragX;
      walker.y = dragY;
    }
    const drop = this.zoneAt(dragX, dragY, layout);
    const rect = drop && drop !== from ? this.zoneRect(drop, layout) : undefined;
    if (rect) {
      halo.setPosition(rect.x, rect.y).setSize(rect.width, rect.height).setVisible(true);
    } else {
      halo.setVisible(false);
    }
  });

  token.on("dragend", (pointer: Phaser.Input.Pointer) => {
    halo.setVisible(false);
    token.setAlpha(1);
    const walker = this.walkers.get(role);
    if (walker) walker.dragging = false;
    this.draggingRole = undefined;
    const drop = this.zoneAt(token.x, token.y, layout);
    // Dropped where they already were, or off the floor entirely: they walk
    // back to their station rather than staying stuck under the cursor.
    if (drop && drop !== from) {
      // Left standing where they were dropped, in the zone they were dropped
      // into, so the walk that follows is the short one onto their slot
      // instead of a march back out of the room they just left.
      walker?.snap({ x: token.x, y: token.y }, drop);
      this.onAction(`assign_${role}_${drop}`);
    }
    void pointer;
    // Whatever the shift asked for while the token was in the air happens
    // now — including the repaint for the assignment just dispatched.
    const owed = this.repaintGate.endDrag();
    if (owed || drop !== undefined) this.paint();
    else this.walkHome(role, from, layout);
  });
}

/** Which zone a pixel belongs to, or `undefined` for none of them. */
private zoneAt(x: number, y: number, layout: RestaurantArenaLayout): Location | undefined {
  const zones: [Location, ArenaRect][] = [
    ["queue", layout.door],
    ["kitchen", layout.kitchen],
    ["pass", layout.pass],
    ["floor", layout.dining],
  ];
  for (const [location, rect] of zones) {
    if (x >= rect.x && x <= rect.x + rect.width && y >= rect.y && y <= rect.y + rect.height) return location;
  }
  return undefined;
}

private zoneRect(location: Location, layout: RestaurantArenaLayout): ArenaRect {
  if (location === "kitchen") return layout.kitchen;
  if (location === "pass") return layout.pass;
  if (location === "queue") return layout.door;
  return layout.dining;
}

/** Send someone back to the station they are still assigned to. */
private walkHome(role: Role, location: Location, layout: RestaurantArenaLayout): void {
  const walker = this.walkers.get(role);
  if (!walker) return;
  const slot = this.stackedSlot(location, this.stackOffset(role, location), layout);
  walker.setTarget(location, this.slotWaypoints(layout, location, slot), layout.spineY);
}

/** This role's place in the queue of staff standing in the same zone. */
private stackOffset(role: Role, location: Location): number {
  let offset = 0;
  for (const worker of this.state.workers) {
    if (worker.role === role) return offset;
    if (this.visualLocation(worker) === location) offset += 1;
  }
  return offset;
}

/**
 * Walks in progress. Tokens are moved in place rather than repainted: a walk
 * is sixty frames of motion, and repainting the floor for each of them would
 * throw away every hotspot under the player's cursor sixty times a second.
 */
update(_time: number, delta: number): void {
  const layout = this.layout;
  if (!layout) return;
  // The staff stop moving when the shift does — a paused floor is paused.
  const speed = this.running ? (this.state.sim?.speed ?? 1) : 0;
  for (const [role, walker] of this.walkers) {
    const token = this.staffTokens.get(role);
    if (role === this.draggingRole) continue;
    const before = walker.walking;
    if (!walker.step(delta, speed)) {
      // The hop that just landed leaves the token parked; give it its idle
      // breathing back so it doesn't read as frozen.
      if (before && !walker.walking && token) this.startIdleBob(token, walker.y, role);
      continue;
    }
    token?.setPosition(walker.x, walker.y);
    const figure = token?.getByName("figure");
    if (figure && "setScale" in figure) {
      (figure as Phaser.GameObjects.Container).setScale(walker.facing, 1);
    }
  }
}

