bun -e '
import { restaurantArenaLayout } from "./overlay/restaurant-arena-layout.ts";
const keys = ["topBar","brief","kitchen","pass","dining","door","doorStand","tickets","feed"];
let bad = 0;
for (let w = 200; w <= 2600; w += 7) {
  for (const h of [180, 240, 300, 420, 480, 640, 740, 900, 1080, 1440, 2000]) {
    const L = restaurantArenaLayout(w, h);
    for (const k of keys) {
      const r = L[k];
      if (r.x < 0 || r.y < 0 || r.x + r.width > w + 0.001 || r.y + r.height > h + 0.001 || r.width < 0 || r.height < 0) {
        if (bad++ < 12) console.log("OUT", w, h, k, JSON.stringify(r));
      }
    }
    for (const [n,p] of Object.entries(L.waypoints)) {
      if (p.x < 0 || p.y < 0 || p.x > w || p.y > h) { if (bad++ < 20) console.log("WP OUT", w,h,n,JSON.stringify(p)); }
    }
    if (L.spineY < L.pass.y || L.spineY > L.pass.y + L.pass.height) { if (bad++<20) console.log("SPINE", w,h,L.spineY, JSON.stringify(L.pass)); }
    if (L.doorStand.width < 56 || L.doorStand.height < 22) { if (bad++<20) console.log("STAND", w,h,JSON.stringify(L.doorStand)); }
  }
}
console.log("violations:", bad);
console.log(JSON.stringify(restaurantArenaLayout(520,740), null, 1));
'

