import { describe, expect, test } from "bun:test";
import {
  BASELINE_HEIGHT,
  BASELINE_WIDTH,
  MAX_SCALE,
  restaurantArenaLayout,
  type ArenaPoint,
  type ArenaRect,
  type RestaurantArenaLayout,
} from "./restaurant-arena-layout.js";

const RECTS = [
  "topBar",
  "brief",
  "kitchen",
  "pass",
  "dining",
  "door",
  "doorStand",
  "tickets",
  "feed",
] as const satisfies readonly (keyof RestaurantArenaLayout)[];

function rects(layout: RestaurantArenaLayout): [string, ArenaRect][] {
  return RECTS.map((key) => [key, layout[key]]);
}

function contains(rect: ArenaRect, point: ArenaPoint): boolean {
  return (
    point.x >= rect.x &&
    point.x <= rect.x + rect.width &&
    point.y >= rect.y &&
    point.y <= rect.y + rect.height
  );
}

/** Every window worth caring about, from a cramped panel to a 4K half-screen. */
const SIZES: [number, number][] = [
  [320, 240],
  [360, 640],
  [420, 400],
  [459, 740],
  [520, 740],
  [600, 480],
  [760, 900],
  [1024, 768],
  [1440, 900],
  [1920, 1080],
  [2560, 1440],
  [3840, 2160],
];

describe("restaurantArenaLayout", () => {
  test("keeps every region inside the canvas at any size", () => {
    for (const [width, height] of SIZES) {
      const layout = restaurantArenaLayout(width, height);
      for (const [name, rect] of rects(layout)) {
        const where = `${name} at ${width}x${height}`;
        expect(rect.width, where).toBeGreaterThanOrEqual(0);
        expect(rect.height, where).toBeGreaterThanOrEqual(0);
        expect(rect.x, where).toBeGreaterThanOrEqual(0);
        expect(rect.y, where).toBeGreaterThanOrEqual(0);
        expect(rect.x + rect.width, where).toBeLessThanOrEqual(width);
        expect(rect.y + rect.height, where).toBeLessThanOrEqual(height);
      }
    }
  });

  test("scale is 1 at the design size and grows with the tighter axis", () => {
    expect(restaurantArenaLayout(BASELINE_WIDTH, BASELINE_HEIGHT).scale).toBe(1);
    // Both axes doubled: the ramp would say 2, the cap says otherwise.
    expect(restaurantArenaLayout(BASELINE_WIDTH * 2, BASELINE_HEIGHT * 2).scale).toBe(MAX_SCALE);
    expect(restaurantArenaLayout(BASELINE_WIDTH * 1.5, BASELINE_HEIGHT * 1.5).scale).toBeCloseTo(1.5, 5);
    // Wide but only just tall enough: no more room for big type than a
    // baseline window has, so it doesn't get any.
    expect(restaurantArenaLayout(4000, BASELINE_HEIGHT).scale).toBe(1);
    // Never shrinks: small windows get the compact layout, not smaller text.
    expect(restaurantArenaLayout(480, 500).scale).toBe(1);
    expect(restaurantArenaLayout(3840, 2160).scale).toBeLessThanOrEqual(MAX_SCALE);
  });

  test("goes compact — and stops growing text — on a small canvas", () => {
    expect(restaurantArenaLayout(440, 740).compact).toBe(true);
    expect(restaurantArenaLayout(1200, 400).compact).toBe(true);
    expect(restaurantArenaLayout(520, 740).compact).toBe(false);
    // A big-but-short window is compact, so it must not scale type up either.
    expect(restaurantArenaLayout(1920, 400).scale).toBe(1);
  });

  test("puts the feed beside the floor once there is width for it", () => {
    const wide = restaurantArenaLayout(900, 700);
    expect(wide.feedBeside).toBe(true);
    // Beside: to the right of the floor column, spanning it top to bottom.
    expect(wide.feed.x).toBeGreaterThanOrEqual(wide.dining.x + wide.dining.width);
    expect(wide.feed.y).toBe(wide.kitchen.y);
    expect(wide.feed.height).toBeGreaterThanOrEqual(wide.kitchen.height);
    expect(wide.tickets.x + wide.tickets.width).toBeLessThanOrEqual(wide.feed.x);

    const narrow = restaurantArenaLayout(520, 740);
    expect(narrow.feedBeside).toBe(false);
    // Stacked: below the ticket rail, full width.
    expect(narrow.feed.y).toBeGreaterThanOrEqual(narrow.tickets.y + narrow.tickets.height);
    expect(narrow.feed.width).toBe(narrow.topBar.width);
  });

  test("stacks the bands in reading order without overlapping", () => {
    for (const [width, height] of SIZES) {
      const layout = restaurantArenaLayout(width, height);
      const where = `${width}x${height}`;
      expect(layout.brief.y, where).toBeGreaterThanOrEqual(layout.topBar.y + layout.topBar.height);
      expect(layout.kitchen.y, where).toBeGreaterThanOrEqual(layout.brief.y + layout.brief.height);
      expect(layout.pass.x, where).toBeGreaterThanOrEqual(layout.kitchen.x + layout.kitchen.width);
      expect(layout.dining.x, where).toBeGreaterThanOrEqual(layout.pass.x + layout.pass.width);
      expect(layout.door.y, where).toBeGreaterThanOrEqual(layout.dining.y + layout.dining.height);
      expect(layout.tickets.y, where).toBeGreaterThanOrEqual(layout.kitchen.y + layout.kitchen.height);
    }
  });

  test("keeps the host stand grabbable however small the window gets", () => {
    for (const [width, height] of SIZES) {
      const stand = restaurantArenaLayout(width, height).doorStand;
      expect(stand.width, `${width}x${height}`).toBeGreaterThanOrEqual(56);
      expect(stand.height, `${width}x${height}`).toBeGreaterThanOrEqual(22);
    }
  });

  test("runs the hallway through the pass, the kitchen and the dining room", () => {
    for (const [width, height] of SIZES) {
      const layout = restaurantArenaLayout(width, height);
      const where = `${width}x${height}`;
      for (const room of [layout.pass, layout.kitchen, layout.dining]) {
        expect(layout.spineY, where).toBeGreaterThanOrEqual(room.y);
        expect(layout.spineY, where).toBeLessThanOrEqual(room.y + room.height);
      }
    }
  });

  test("parks staff in the rooms their locations name", () => {
    for (const [width, height] of SIZES) {
      const layout = restaurantArenaLayout(width, height);
      const where = `${width}x${height}`;
      expect(contains(layout.kitchen, layout.waypoints.kitchen), where).toBe(true);
      expect(contains(layout.pass, layout.waypoints.pass), where).toBe(true);
      expect(contains(layout.dining, layout.waypoints.floor), where).toBe(true);
      // The queue waypoint is the host stand itself, not the door band at large.
      expect(contains(layout.doorStand, layout.waypoints.queue), where).toBe(true);
    }
  });

  test("is a pure function of the box", () => {
    expect(restaurantArenaLayout(1024, 768)).toEqual(restaurantArenaLayout(1024, 768));
  });
});

