        const where = `${name} at ${width}x${height}`;
        expect(rect.width, where).toBeGreaterThanOrEqual(0);
        expect(rect.height, where).toBeGreaterThanOrEqual(0);
        expect(rect.x, where).toBeGreaterThanOrEqual(0);
        expect(rect.y, where).toBeGreaterThanOrEqual(0);
        expect(rect.x + rect.width, where).toBeLessThanOrEqual(width);
        expect(rect.y + rect.height, where).toBeLessThanOrEqual(height);
      }
    }
  });

  test("scale is 1 at the design size and grows with the tighter axis", () => {
    expect(restaurantArenaLayout(BASELINE_WIDTH, BASELINE_HEIGHT).scale).toBe(1);
    // Both axes doubled: the ramp would say 2, the cap says otherwise.
    expect(restaurantArenaLayout(BASELINE_WIDTH * 2, BASELINE_HEIGHT * 2).scale).toBe(MAX_SCALE);
    expect(restaurantArenaLayout(BASELINE_WIDTH * 1.5, BASELINE_HEIGHT * 1.5).scale).toBeCloseTo(1.5, 5);
