      expect(contains(layout.doorStand, layout.waypoints.queue), where).toBe(true);
    }
  });

  test("is a pure function of the box", () => {
    expect(restaurantArenaLayout(1024, 768)).toEqual(restaurantArenaLayout(1024, 768));
  });
});

