import { describe, expect, test } from "bun:test";
import { restaurantArenaLayout } from "./restaurant-arena-layout.js";
import {
  bfsPath,
  corridorPoints,
  hopDurationMs,
  StaffWalker,
  WALK_GRAPH,
  WALK_SPEED_PX_PER_SEC,
  type Point,
  type WalkNode,
} from "./staff-walk.js";

const layout = restaurantArenaLayout(520, 740);
const waypoints = layout.waypoints;
const spineY = layout.spineY;

/** Walk a walker to a standstill, one 16ms frame at a time. */
function runToRest(walker: StaffWalker, speed = 1): number {
  let frames = 0;
  while (walker.walking && frames < 10_000) {
    walker.step(16, speed);
    frames += 1;
  }
  return frames;
}

describe("WALK_GRAPH", () => {
  test("is one hallway: kitchen — pass — floor — queue", () => {
    expect(WALK_GRAPH.kitchen).toEqual(["pass"]);
    expect(WALK_GRAPH.queue).toEqual(["floor"]);
    // Both middles connect both ways, so nothing is a dead end.
    expect([...WALK_GRAPH.pass].sort()).toEqual(["floor", "kitchen"]);
    expect([...WALK_GRAPH.floor].sort()).toEqual(["pass", "queue"]);
  });

  test("has no edge that isn't mutual", () => {
    for (const [node, neighbours] of Object.entries(WALK_GRAPH) as [WalkNode, readonly WalkNode[]][]) {
      for (const neighbour of neighbours) {
        expect(WALK_GRAPH[neighbour]).toContain(node);
      }
    }
  });
});

describe("bfsPath", () => {
  test("routes the kitchen to the door through the pass and the dining room", () => {
    expect(bfsPath("kitchen", "queue")).toEqual(["kitchen", "pass", "floor", "queue"]);
    expect(bfsPath("queue", "kitchen")).toEqual(["queue", "floor", "pass", "kitchen"]);
  });

  test("never skips a through-station", () => {
    for (const from of Object.keys(WALK_GRAPH) as WalkNode[]) {
      for (const to of Object.keys(WALK_GRAPH) as WalkNode[]) {
        const path = bfsPath(from, to);
        expect(path[0]).toBe(from);
        expect(path[path.length - 1]).toBe(to);
        // Consecutive nodes in the path are always neighbours.
        for (let i = 1; i < path.length; i++) {
          expect(WALK_GRAPH[path[i - 1]!]).toContain(path[i]!);
        }
      }
    }
  });

  test("standing still is a path of one", () => {
    expect(bfsPath("pass", "pass")).toEqual(["pass"]);
  });
});

describe("corridorPoints", () => {
  test("rides the hallway instead of cutting across the room", () => {
    const start = waypoints.kitchen;
    const points = corridorPoints(start, bfsPath("kitchen", "queue"), waypoints, spineY);
    expect(points.length).toBeGreaterThan(0);

    let previous: Point = start;
    for (const point of points) {
      // Axis-aligned throughout: no diagonal shortcut over the furniture.
      const straight = Math.abs(point.x - previous.x) < 0.5 || Math.abs(point.y - previous.y) < 0.5;
      expect(straight).toBe(true);
      previous = point;
    }
    // Sideways travel only ever happens on the hallway line.
    for (let i = 1; i < points.length; i++) {
      const from = points[i - 1]!;
      const to = points[i]!;
      if (Math.abs(to.x - from.x) >= 0.5) {
        expect(from.y).toBeCloseTo(spineY, 5);
        expect(to.y).toBeCloseTo(spineY, 5);
      }
    }
    expect(points[points.length - 1]).toEqual(waypoints.queue);
  });

  test("a walk that is already on the hallway stays a straight line", () => {
    const start = { x: 10, y: spineY };
    const points = corridorPoints(start, ["floor"], { ...waypoints, floor: { x: 300, y: spineY } }, spineY);
    expect(points).toEqual([{ x: 300, y: spineY }]);
  });

  test("has nothing to walk when it is already there", () => {
    expect(corridorPoints(waypoints.pass, ["pass"], waypoints, spineY)).toEqual([]);
  });
});

describe("hopDurationMs", () => {
  test("takes a second to cross 200px", () => {
    expect(hopDurationMs({ x: 0, y: 0 }, { x: WALK_SPEED_PX_PER_SEC, y: 0 })).toBeCloseTo(1000, 5);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 0, y: 100 })).toBeCloseTo(500, 5);
    expect(hopDurationMs({ x: 30, y: 40 }, { x: 30, y: 40 })).toBe(0);
    // Diagonal hops are measured as the crow flies, not as the taxi drives.
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 120, y: 160 })).toBeCloseTo(1000, 5);
  });
});

describe("StaffWalker", () => {
  test("starts parked on its slot", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    expect(walker.node).toBe("kitchen");
    expect(walker.walking).toBe(false);
    expect({ x: walker.x, y: walker.y }).toEqual(waypoints.kitchen);
    expect(walker.step(16, 1)).toBe(false);
  });

  test("walks the whole hallway and arrives on the slot", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    expect(walker.walking).toBe(true);
    // Still in the kitchen until it actually gets there.
    expect(walker.node).toBe("kitchen");
    expect(walker.step(16, 1)).toBe(true);

    const frames = runToRest(walker);
    expect(frames).toBeGreaterThan(1);
    expect(walker.walking).toBe(false);
    expect(walker.node).toBe("queue");
    expect(walker.x).toBeCloseTo(waypoints.queue.x, 5);
    expect(walker.y).toBeCloseTo(waypoints.queue.y, 5);
  });

  test("takes about as long as the corridor is", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    const points = corridorPoints(waypoints.kitchen, bfsPath("kitchen", "queue"), waypoints, spineY);
    let expected = 0;
    let previous: Point = waypoints.kitchen;
    for (const point of points) {
      expected += hopDurationMs(previous, point);
      previous = point;
    }
    // One 16ms frame of overshoot at the end is the whole tolerance.
    expect(runToRest(walker) * 16).toBeGreaterThanOrEqual(expected);
    expect(runToRest(walker) * 16).toBeLessThan(expected + 32);
  });

  test("runs at the shift's speed, and stands still when it is paused", () => {
    const paused = new StaffWalker("kitchen", waypoints.kitchen);
    paused.setTarget("floor", waypoints, spineY);
    expect(paused.step(16, 0)).toBe(false);
    expect(paused.walking).toBe(true);

    const fast = new StaffWalker("kitchen", waypoints.kitchen);
    fast.setTarget("floor", waypoints, spineY);
    const slow = new StaffWalker("kitchen", waypoints.kitchen);
    slow.setTarget("floor", waypoints, spineY);
    expect(runToRest(fast, 4)).toBeLessThan(runToRest(slow, 1));
  });

  test("faces where it is going", () => {
    const walker = new StaffWalker("queue", waypoints.queue);
    walker.setTarget("kitchen", waypoints, spineY);
    runToRest(walker);
    // The kitchen is stage left of the door.
    expect(walker.facing).toBe(-1);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(16, 1);
    expect(walker.facing).toBe(1);
  });

  test("stands down while the player is holding it", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(100, 1);
    walker.dragging = true;
    const x = walker.x;
    expect(walker.step(100, 1)).toBe(false);
    expect(walker.x).toBe(x);
    walker.dragging = false;
    expect(walker.step(100, 1)).toBe(true);
  });

  test("snaps onto a dropped-on zone with no walk left over", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(200, 1);
    walker.snap({ x: 400, y: 410 }, "queue");
    expect(walker.walking).toBe(false);
    expect(walker.node).toBe("queue");
    expect({ x: walker.x, y: walker.y }).toEqual({ x: 400, y: 410 });
    expect(walker.step(16, 1)).toBe(false);

    // …and then a short walk onto its actual slot, without leaving the room.
    walker.setTarget("queue", waypoints, spineY);
    runToRest(walker);
    expect(walker.x).toBeCloseTo(waypoints.queue.x, 5);
    expect(walker.y).toBeCloseTo(waypoints.queue.y, 5);
  });

  test("re-targets mid-walk from where it actually is", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(300, 1);
    // Called back before it got there: it must not first march to the door.
    walker.setTarget("kitchen", waypoints, spineY);
    const frames = runToRest(walker);
    expect(walker.node).toBe("kitchen");
    expect(frames * 16).toBeLessThan(hopDurationMs(waypoints.kitchen, waypoints.queue) * 2);
    expect(walker.x).toBeCloseTo(waypoints.kitchen.x, 5);
    expect(walker.y).toBeCloseTo(waypoints.kitchen.y, 5);
  });
});

