import { describe, expect, test } from "bun:test";
import { RepaintGate } from "./restaurant-arena-repaint-gate.js";

describe("RepaintGate", () => {
  test("paints immediately when nothing is being dragged", () => {
    const gate = new RepaintGate();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
    expect(gate.requestPaint()).toBe(true);
    // Nothing was held, so there is nothing to replay.
    expect(gate.endDrag()).toBe(false);
  });

  test("holds a paint asked for mid-drag until the drop", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.isDragging).toBe(true);
    expect(gate.requestPaint()).toBe(false);
    expect(gate.endDrag()).toBe(true);
    expect(gate.isDragging).toBe(false);
  });

  test("owes exactly one repaint however many ticks land during the drag", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    for (let i = 0; i < 12; i++) expect(gate.requestPaint()).toBe(false);
    expect(gate.endDrag()).toBe(true);
    // The one owed paint has been handed over; it isn't owed twice.
    expect(gate.endDrag()).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("owes nothing for a drag that asked for nothing", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.endDrag()).toBe(false);
  });

  test("a resize drops the drag and clears anything owed", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.resize();
    expect(gate.isDragging).toBe(false);
    // The resize repainted from scratch, so the held paint is already satisfied
    // — and a dragend straggling in after it owes nothing.
    expect(gate.endDrag()).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("goes back to normal after a resize", () => {
    const gate = new RepaintGate();
    gate.resize();
    gate.beginDrag();
    expect(gate.requestPaint()).toBe(false);
    expect(gate.endDrag()).toBe(true);
  });
});

