    // back to their station rather than staying stuck under the cursor.
    else this.walkHome(role, from, layout);
  });
}

/** Which zone a pixel belongs to, or `undefined` for none of them. */
private zoneAt(x: number, y: number, layout: RestaurantArenaLayout): Location | undefined {
  const zones: [Location, ArenaRect][] = [
    ["queue", layout.door],
    ["kitchen", layout.kitchen],
    ["pass", layout.pass],
    ["floor", layout.dining],
  ];
  for (const [location, rect] of zones) {
    if (x >= rect.x && x <= rect.x + rect.width && y >= rect.y && y <= rect.y + rect.height) return location;
  }
  return undefined;
}

private zoneRect(location: Location, layout: RestaurantArenaLayout): ArenaRect {
  if (location === "kitchen") return layout.kitchen;
  if (location === "pass") return layout.pass;
  if (location === "queue") return layout.door;
  return layout.dining;
}

/** Send someone back to the station they are still assigned to. */
private walkHome(role: Role, location: Location, layout: RestaurantArenaLayout): void {
  const walker = this.walkers.get(role);
  if (!walker) return;
  const slot = this.stackedSlot(location, this.stackOffset(role, location), layout);
  walker.setTarget(location, this.slotWaypoints(layout, location, slot), layout.spineY);
}

/** This role's place in the queue of staff standing in the same zone. */
private stackOffset(role: Role, location: Location): number {
  let offset = 0;
  for (const worker of this.state.workers) {
    if (worker.role === role) return offset;
    if (this.visualLocation(worker) === location) offset += 1;
