669	    const rawStationHeight = (zone.height - (top - zone.y) - pad * (stations.length + 1)) / stations.length;
670	    const stationHeight = Math.min(compact ? 40 : 76, Math.max(14, rawStationHeight));
671	    const groupHeight = stationHeight * stations.length + pad * (stations.length - 1);
672	    const groupTop = top + Math.max(0, (zone.height - (top - zone.y) - groupHeight) / 2);
673	
674	    stations.forEach((station, index) => {
675	      const y = groupTop + index * (stationHeight + pad);
676	      const rect = { x: zone.x + pad, y, width: zone.width - pad * 2, height: stationHeight };
677	      g.fillStyle(station.color, station.dim ? 0.6 : 1);
678	      g.fillRoundedRect(rect.x, rect.y, rect.width, rect.height, 3);
679	      g.lineStyle(1, COLORS.kitchenDark, 0.8);
680	      g.strokeRoundedRect(rect.x, rect.y, rect.width, rect.height, 3);
681	      const broken = station.label === "OVEN" && oven?.status === "failed";
682	      this.add
683	        .text(zone.x + zone.width / 2, y + stationHeight / 2 - (station.sub ? 4 : 0), station.label, {
684	          color: broken ? "#ffffff" : "#2b2118",
685	          fontFamily: MONO,
686	          fontSize: compact ? this.fs(6) : this.fs(8),
687	          fontStyle: "bold",
688	        })
689	        .setOrigin(0.5);
690	      if (station.sub) {
691	        this.add
692	          .text(zone.x + zone.width / 2, y + stationHeight / 2 + 5, station.sub, {
693	            color: broken ? "#ffe2e2" : "#5c4a3a",
694	            fontFamily: MONO,
695	            fontSize: compact ? this.fs(5) : this.fs(6),
696	            fontStyle: "bold",
697	          })
698	          .setOrigin(0.5);
699	      }
700	      if (station.action) this.hotspot(rect, station.action, station.tip);
701	    });
702	  }
703	
704	  private drawPass(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
705	    const zone = layout.pass;
706	    this.zonePanel(g, zone, COLORS.pass, "PASS", layout.compact, true);
707	    this.hotspot(zone, "verify_substitution", "Verify the ticket");
708	    const y = zone.y + zone.height * 0.6;
709	    g.fillStyle(0x7b4c2e);
710	    g.fillRoundedRect(zone.x + 3, y, zone.width - 6, layout.compact ? 12 : 18, 3);
711	    // Plates waiting on the pass = orders cooked but not yet run to a table.
712	    const ready = this.state.orders.filter((order) => order.status === "ready").length;
713	    for (let i = 0; i < Math.min(3, ready); i++) {
714	      g.fillStyle(0xfff3d6);
715	      g.fillCircle(zone.x + zone.width / 2, y + 4 + i * (layout.compact ? 5 : 7), layout.compact ? 2.5 : 3.5);
716	    }
717	    if (ready > 0) {
718	      this.add
719	        .text(zone.x + zone.width / 2, zone.y + zone.height - 4, `${ready}`, {
720	          color: "#2b2118",
721	          fontFamily: MONO,
722	          fontSize: layout.compact ? this.fs(7) : this.fs(9),
723	          fontStyle: "bold",
724	        })
725	        .setOrigin(0.5, 1);
726	    }
727	  }
