605	  private zonePanel(
606	    g: Phaser.GameObjects.Graphics,
607	    zone: ArenaRect,
608	    color: number,
609	    label: string,
610	    compact: boolean,
611	    vertical = false,
612	  ): void {
613	    g.fillStyle(color);
614	    g.fillRoundedRect(zone.x, zone.y, zone.width, zone.height, compact ? 3 : 5);
615	    g.lineStyle(2, COLORS.ink, 0.5);
616	    g.strokeRoundedRect(zone.x, zone.y, zone.width, zone.height, compact ? 3 : 5);
617	    const text = this.add.text(zone.x + 5, zone.y + 4, label, {
618	      color: "#3b2b20",
619	      fontFamily: "Arial Narrow, sans-serif",
620	      fontSize: compact ? this.fs(7) : this.fs(9),
621	      fontStyle: "bold",
622	    });
623	    if (vertical) text.setOrigin(0.5, 0).setAngle(90).setPosition(zone.x + zone.width / 2, zone.y + zone.height / 2);
624	  }
