729	  private drawDining(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
730	    const zone = layout.dining;
731	    const compact = layout.compact;
732	    this.zonePanel(g, zone, COLORS.dining, "DINING", compact);
733	
734	    const tables = this.state.tables.slice(0, 4);
735	    const top = zone.y + (compact ? 15 : 19);
736	    const available = Math.max(24, zone.height - (top - zone.y) - 4);
737	    const cols = tables.length > 2 ? 2 : tables.length || 1;
738	    const rows = Math.ceil(tables.length / cols) || 1;
739	
740	    tables.forEach((table, index) => {
741	      const col = index % cols;
742	      const row = Math.floor(index / cols);
743	      const cx = zone.x + (zone.width * (col + 0.5)) / cols;
744	      const cy = top + (available * (row + 0.5)) / rows;
745	      // Capped at a fixed 18px, tables read as a sparse handful of dots on a
746	      // real desktop window where this zone is much bigger than a 520px
747	      // canvas — let them grow with the room, not just with the cell they
748	      // have to fit in.
749	      const fitsCell = Math.min(zone.width / cols, available / rows) * 0.3;
750	      const styleCap = compact ? 13 : Math.min(32, 18 + Math.max(0, zone.width - 360) * 0.03);
751	      const radius = Math.max(8, Math.min(styleCap, fitsCell));
752	
753	      // Chairs first so the table top sits over them.
754	      const seats = Math.min(table.seats, 4);
755	      for (let seat = 0; seat < seats; seat++) {
756	        const angle = (Math.PI * 2 * seat) / seats - Math.PI / 2;
757	        g.fillStyle(0x8a5a34);
758	        g.fillCircle(cx + Math.cos(angle) * (radius + 5), cy + Math.sin(angle) * (radius + 5), compact ? 2.5 : 3.5);
759	      }
760	      g.fillStyle(table.status === "occupied" ? COLORS.occupied : COLORS.empty);
761	      g.fillCircle(cx, cy, radius);
762	      g.lineStyle(2, COLORS.cream, 0.85);
763	      g.strokeCircle(cx, cy, radius);
764	
765	      const order = this.state.orders.find((o) => o.tableId === table.id && o.status !== "served" && o.status !== "cancelled");
766	      this.add
767	        .text(cx, cy, table.id.replace("table-", "T"), {
768	          color: "#ffffff",
769	          fontFamily: MONO,
770	          fontSize: compact ? this.fs(7) : this.fs(9),
771	          fontStyle: "bold",
772	        })
773	        .setOrigin(0.5);
774	
775	      if (order) {
776	        // A plate icon on the table once the food is up, so the floor shows
777	        // what the ticket rail says.
778	        if (order.status === "ready") {
779	          g.fillStyle(0xfff8e7);
780	          g.fillCircle(cx + radius * 0.7, cy - radius * 0.7, compact ? 3 : 4);
781	        }
782	        if (order.allergy) {
783	          this.add
784	            .text(cx, cy - radius - (compact ? 6 : 8), "!", {
785	              color: "#ffffff",
786	              backgroundColor: "#c73535",
787	              fontFamily: MONO,
788	              fontSize: compact ? this.fs(6) : this.fs(8),
789	              fontStyle: "bold",
790	              padding: { x: 3, y: 0 },
791	            })
792	            .setOrigin(0.5);
793	        }
794	        const index3 = Number((table.id.match(/\d+/) ?? ["0"])[0]);
795	        if (index3 >= 1 && index3 <= 3 && order.priority !== "high") {
796	          this.hotspot(
797	            { x: cx - radius - 4, y: cy - radius - 4, width: radius * 2 + 8, height: radius * 2 + 8 },
798	            `rush_table_${index3}`,
799	            `Rush ${table.id.replace("table-", "table ")}`,
800	          );
801	        }
802	      }
803	    });
804	  }
