806	  /** The door: who is waiting, and a host stand you can actually see. */
807	  private drawDoor(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
808	    const zone = layout.door;
809	    const compact = layout.compact;
810	    const held = Boolean(this.state.seatingHeld);
811	    const waiting = this.state.waiting ?? [];
812	    const crowded = waiting.length >= 3 && !held;
813	    this.zonePanel(g, zone, held ? 0xc9a4a0 : COLORS.door, "DOOR", compact);
814	    if (held) {
815	      g.lineStyle(3, COLORS.failed, 0.95);
816	      g.strokeRoundedRect(zone.x, zone.y, zone.width, zone.height, compact ? 3 : 5);
817	      this.add.rectangle(zone.x + 2, zone.y + 1, zone.width - 4, 3, COLORS.failed).setOrigin(0, 0).setDepth(5);
818	    }
819	
820	    const stand = layout.doorStand;
821	    const fill = held ? COLORS.failed : crowded ? 0x4a3a2c : 0x5a4636;
822	    const bg = this.add.rectangle(stand.x, stand.y, stand.width, stand.height, fill).setOrigin(0, 0);
823	    bg.setStrokeStyle(2, held || crowded ? COLORS.cream : COLORS.ink, held ? 0.95 : 0.55);
824	    bg.setDepth(6);
825	    const titleX = stand.x + stand.width / 2 + (held ? 6 : 0);
826	    if (held) {
827	      const lockX = stand.x + 10;
828	      const lockY = stand.y + stand.height / 2;
829	      const shackle = this.add.circle(lockX, lockY - 5, 3.5, fill, 0).setDepth(7);
830	      shackle.setStrokeStyle(2, COLORS.cream, 0.95);
831	      this.add.rectangle(lockX, lockY + 1, 8, 7, COLORS.cream).setOrigin(0.5).setDepth(7);
832	    }
833	    const title = held ? "DOOR HELD" : "HOLD DOOR";
834	    this.add
835	      .text(titleX, stand.y + (compact ? 6 : 8), title, {
836	        color: "#fff3d6",
837	        fontFamily: MONO,
838	        fontSize: compact ? this.fs(6) : this.fs(8),
839	        fontStyle: "bold",
840	      })
841	      .setOrigin(0.5, 0)
842	      .setDepth(7);
843	    this.add
844	      .text(stand.x + stand.width / 2, stand.y + stand.height - (compact ? 4 : 5), held ? "H to open" : "press H", {
845	        color: "#f2cc5c",
846	        fontFamily: MONO,
847	        fontSize: compact ? this.fs(5) : this.fs(6),
848	        fontStyle: "bold",
849	      })
850	      .setOrigin(0.5, 1)
851	      .setDepth(7);
852	    this.hotspot(stand, "hold_seating", held ? "H — open the door and start seating" : "H — stop seating new tables", 8);
853	    if (crowded) this.tweens.add({ targets: bg, alpha: 0.55, duration: 420, yoyo: true, repeat: -1 });
854	
855	    const textLeft = stand.x + stand.width + 6;
856	    if (waiting.length === 0) {
857	      this.add
858	        .text(textLeft, zone.y + zone.height / 2 + 2, held ? "Held — nobody waiting" : "Nobody waiting", {
859	          color: "#3b2b20",
860	          fontFamily: MONO,
861	          fontSize: compact ? this.fs(6) : this.fs(8),
862	        })
863	        .setOrigin(0, 0.5);
864	      return;
865	    }
866	
867	    const y = zone.y + zone.height * 0.62;
868	    const cardWidth = compact ? 26 : 34;
869	    waiting.slice(0, 5).forEach((party, index) => {
870	      const x = textLeft + index * (cardWidth + 4);
871	      g.fillStyle(held ? 0xe8d4c4 : 0xfff3d6);
872	      g.fillRoundedRect(x, y - (compact ? 9 : 11), cardWidth, compact ? 15 : 19, 3);
873	      this.add
874	        .text(x + cardWidth / 2, y - (compact ? 3 : 4), `×${party.size}`, {
875	          color: "#2b2118",
876	          fontFamily: MONO,
877	          fontSize: compact ? this.fs(7) : this.fs(9),
878	          fontStyle: "bold",
879	        })
880	        .setOrigin(0.5);
881	      const barWidth = cardWidth - 6;
882	      const patience = Math.max(0, Math.min(1, party.patience));
883	      this.add.rectangle(x + 3, y + (compact ? 3 : 4), barWidth, 3, 0x4a3a2c, 0.7).setOrigin(0, 0.5);
884	      const barFill = this.add
885	        .rectangle(x + 3, y + (compact ? 3 : 4), Math.max(1, barWidth * patience), 3, loadColor(1 - patience))
886	        .setOrigin(0, 0.5);
887	      if (patience < 0.3) this.tweens.add({ targets: barFill, alpha: 0.3, duration: 380, yoyo: true, repeat: -1 });
888	    });
889	  }
890	
