// ── Staff avatars ────────────────────────────────────────────────────

private visualLocation(worker: RestaurantArenaState["workers"][number]): Location {
  // Holding the door plants the host on the stand so the lock is a person,
  // not a chip. A host already assigned into the kitchen stays there.
  if (
    worker.role === "host" &&
    this.state.seatingHeld &&
    (worker.location === "queue" || worker.location === "floor")
  ) {
    return "queue";
  }
  return worker.location;
}

private stackedSlot(location: Location, offset: number, layout: RestaurantArenaLayout): ArenaPoint {
  const step = layout.compact ? 17 : this.px(22);
  const slot = layout.waypoints[location];
  // Staff at the door stand *beside* the host stand rather than on top of it:
  // the stand carries the hold-the-door control, and a token parked over it
  // would eat the click.
  if (location !== "queue") return { x: slot.x + offset * step, y: slot.y };
  const lead = layout.doorStand.width / 2 + step / 2;
  const room = layout.door.x + layout.door.width - step / 2;
  return { x: Math.min(slot.x + lead + offset * step, room), y: slot.y };
}

private drawWorkers(layout: RestaurantArenaLayout): void {
  const compact = layout.compact;
  const offsets = new Map<Location, number>();
  this.staffTokens.clear();

  for (const worker of this.state.workers) {
    const location = this.visualLocation(worker);
    const offset = offsets.get(location) ?? 0;
    offsets.set(location, offset + 1);
    const slot = this.stackedSlot(location, offset, layout);
    // The walker owns the pixel position; the slot is only where it is
    // *heading*. A repaint mid-walk (or mid-drag) therefore rebuilds the
    // token where the person currently is, not back at their station.
    const walker = this.walker(worker.role, location, slot);
    if (walker.node !== location || (!walker.walking && !walker.dragging && this.awayFrom(walker, slot))) {
      walker.setTarget(location, this.slotWaypoints(layout, location, slot), layout.spineY);
    }

    const token = this.buildAvatar(walker.x, walker.y, worker.role, worker.load, compact);
    // Somebody on the move doesn't idle-bob: that tween owns the token's y,
    // and `update` is about to own it instead.
    if (walker.walking || walker.dragging) this.tweens.killTweensOf(token);
    this.staffTokens.set(worker.role, token);
    const heldHost = worker.role === "host" && Boolean(this.state.seatingHeld) && location === "queue";
    const status = heldHost ? "acting" : (this.workerStatuses.get(worker.role) ?? this.workerStatus(worker));
    this.drawWorkerBadge(token, status, compact, heldHost);
    this.drawSpeechBubble(token, worker.role, compact);
    this.makeDraggable(token, worker.role, location, layout);
  }
}

private walker(role: Role, location: Location, slot: ArenaPoint): StaffWalker {
  const existing = this.walkers.get(role);
  if (existing) return existing;
  const walker = new StaffWalker(location, slot);
  this.walkers.set(role, walker);
  return walker;
}

private awayFrom(walker: StaffWalker, slot: ArenaPoint): boolean {
  return Math.hypot(walker.x - slot.x, walker.y - slot.y) > 1;
}

/**
 * The walk graph's waypoints, with this walker's own stacked slot standing in
 * for the destination — two cooks in the same kitchen shouldn't finish their
 * walks standing inside each other.
 */
private slotWaypoints(
  layout: RestaurantArenaLayout,
  location: Location,
  slot: ArenaPoint,
): Record<Location, ArenaPoint> {
  return { ...layout.waypoints, [location]: slot };
}

/**
 * Drag a member of staff onto another zone to reassign them — the same
 * `assign_<role>_<location>` action the keyboard and the agents use, except
 * you point at where you want them.
 *
 * Dropping is the only part that talks to the game. Everything before it is
 * local: the token follows the pointer, the zone under it lights up, and any
 * repaint the shift asks for in the meantime is held by the gate so the thing
 * being dragged is still there to be dropped.
 */
private makeDraggable(
  token: Phaser.GameObjects.Container,
  role: Role,
  from: Location,
  layout: RestaurantArenaLayout,
): void {

