293	  private button(
294	    rect: ArenaRect,
295	    label: string,
296	    action: string,
297	    opts: { fill?: number; text?: string; size?: number; tip?: string; depth?: number; dispatch?: (action: string) => void } = {},
298	  ): void {
299	    const depth = opts.depth ?? 6;
300	    const bg = this.add.rectangle(rect.x, rect.y, rect.width, rect.height, opts.fill ?? 0x4a3a2c).setOrigin(0, 0);
301	    bg.setStrokeStyle(1, COLORS.cream, 0.35);
302	    bg.setDepth(depth);
303	    const text = this.add
304	      .text(rect.x + rect.width / 2, rect.y + rect.height / 2, label, {
305	        color: opts.text ?? "#fff3d6",
306	        fontFamily: MONO,
307	        fontSize: this.fs(opts.size ?? 9),
308	        fontStyle: "bold",
309	      })
310	      .setOrigin(0.5)
311	      .setDepth(depth + 1);
312	    const zone = this.hotspot(rect, action, opts.tip, depth + 2, opts.dispatch);
313	    zone.on("pointerover", () => bg.setFillStyle(Phaser.Display.Color.ValueToColor(opts.fill ?? 0x4a3a2c).lighten(18).color));
314	    zone.on("pointerout", () => bg.setFillStyle(opts.fill ?? 0x4a3a2c));
315	    void text;
316	  }
317	
318	  create(): void {
319	    // Every state change repaints from scratch, which destroys the zone the
320	    // cursor is sitting on and builds a new one in its place. Phaser only
321	    // re-tests what is under a *stationary* pointer when the pointer moves,
322	    // so without polling the second of two clicks on the same button — speed
323	    // 1x→2x→4x, most obviously — lands on nothing and is silently dropped.
324	    this.input.setPollAlways();
325	    // A click on a member of staff is a click, not a one-pixel drag: the host
326	    // token sits on the door stand, whose control has to stay clickable.
327	    this.input.dragDistanceThreshold = 4;
328	    this.patchTextResolution();
329	    this.applyHiDpi();
330	    this.paint();
331	    // The stage can still be settling when Phaser boots, and a paint sized off
332	    // a half-laid-out parent leaves a blank canvas until something resizes it.
333	    // There's no further "resize" event to catch that later, on purpose —
334	    // see `mountRestaurantArenaScene`, which tears down and boots a fresh
335	    // scene for any genuine later resize rather than mutating a live one.
336	    this.time.delayedCall(0, () => this.resize());
337	  }

