530	          color: "#2b2118",
531	          backgroundColor: this.state.decision ? "#f2cc5c" : "#8d8378",
532	          fontFamily: MONO,
533	          fontSize: compact ? this.fs(6) : this.fs(7),
534	          fontStyle: "bold",
535	          padding: { x: 3, y: 1 },
536	        })
537	        .setOrigin(0, 0.5);
538	      if (this.state.decision) {
539	        this.tweens.add({ targets: chip, alpha: 0.45, duration: 620, yoyo: true, repeat: -1 });
540	      }
541	      x += chip.width + pad;
542	    }
543	
544	    const { tick, maxTicks } = this.state.episode;
545	    const progress = maxTicks > 0 ? Math.min(1, Math.max(0, tick / maxTicks)) : 0;
546	
547	    // Restart sits at the hard-right edge; money and reputation sit just
548	    // inside it, and the progress bar takes whatever slack is left.
549	    const restartX = bar.x + bar.width - pad - navWidth;
550	    this.button(
551	      { x: restartX, y: bar.y + (bar.height - size) / 2, width: navWidth, height: size },
552	      "↻",
553	      "restart",
554	      { size: compact ? 10 : 12, tip: "Restart the shift", dispatch: () => this.onUi("restart") },
555	    );
556	    const helpX = restartX - pad - navWidth;
557	    this.button(
558	      { x: helpX, y: bar.y + (bar.height - size) / 2, width: navWidth, height: size },
559	      "?",
560	      "help",
561	      { size: compact ? 10 : 12, tip: "How to Play", dispatch: () => this.onUi("help") },
562	    );
563	    const rightEdge = helpX - pad;
564	
565	    // Takings read against tonight's target, so the number always means
566	    // something — "$96" alone tells the player nothing.
567	    const goalCash = this.state.goal?.cash;
568	    const amount = Math.round(this.state.outcomes.cash);
569	    const formattedCash = amount < 0 ? `-$${Math.abs(amount)}` : `$${amount}`;
570	    const cash = goalCash ? `${formattedCash}/$${goalCash}` : formattedCash;
571	    // A 1-5 rating reads at a glance the way a percentage never does —
572	    // "3/5" is a milestone a player recognizes instantly, not a figure they
573	    // have to interpret.
574	    const stars = Math.max(1, Math.min(5, Math.round((this.state.reputation ?? 50) / 20)));
575	    const rating = `${stars}/5`;
576	    const onTarget = !goalCash || this.state.outcomes.cash >= goalCash;
577	    const cashText = this.add
578	      .text(rightEdge, bar.y + bar.height / 2 - (compact ? 5 : this.px(6)), cash, {
579	        color: onTarget ? "#7ddc9f" : "#e8ddcc",
580	        fontFamily: MONO,
581	        fontSize: compact ? this.fs(10) : this.fs(12),
582	        fontStyle: "bold",
583	      })
584	      .setOrigin(1, 0.5);
585	    const repText = this.add
586	      .text(rightEdge, bar.y + bar.height / 2 + (compact ? 6 : this.px(7)), `${rating}   ${this.state.outcomes.completed} served`, {
587	        color: "#f2cc5c",
588	        fontFamily: MONO,
589	        fontSize: compact ? this.fs(7) : this.fs(9),
590	      })
591	      .setOrigin(1, 0.5);
592	
593	    const trackX = x + pad;
594	    const trackWidth = Math.max(16, rightEdge - Math.max(cashText.width, repText.width) - pad - trackX);
595	    const trackHeight = compact ? 4 : this.px(6);
596	    const trackY = bar.y + (bar.height - trackHeight) / 2;
597	    g.fillStyle(0x4a3a2c);
598	    g.fillRoundedRect(trackX, trackY, trackWidth, trackHeight, trackHeight / 2);
599	    if (progress > 0) {
600	      g.fillStyle(COLORS.pass);
601	      g.fillRoundedRect(trackX, trackY, Math.max(trackHeight, trackWidth * progress), trackHeight, trackHeight / 2);
602	    }
603	  }
