/**
 * The canvas box changed (or settled) under us. A resize repaints from
 * scratch, so it also cancels anything the gate was holding — nothing owed
 * survives a layout that no longer matches the coordinates it was owed for.
 */
resize(): void {
  this.repaintGate.resize();
  this.releaseDrag();
  this.applyHiDpi();
  this.paint();
}

/**
 * Every repaint outside a paint of our own goes through here: it happens now
 * if nothing is being dragged, and is owed until the drop if it is.
 */
private requestRepaint(): void {
  if (this.repaintGate.requestPaint()) this.paint();
}

/** Forget an in-flight drag: its token and its drop coordinates are gone. */
private releaseDrag(): void {
  const walker = this.draggingRole ? this.walkers.get(this.draggingRole) : undefined;
  if (walker) walker.dragging = false;
  this.draggingRole = undefined;
}

/**
