1	/**
2	 * Staff movement across the Restaurant Arena floor.
3	 *
4	 * The floor is one hallway, not a set of teleport pads: kitchen — pass — floor
5	 * — queue, in that order. The pass and the dining room are through-stations, so
6	 * a cook sent to the door walks out through the pass and across the dining
7	 * room to get there. That is the whole point of animating the move at all —
8	 * a token that teleports says nothing, while one that has to cross the room
9	 * shows the player what an assignment actually costs.
10	 *
11	 * `corridorPoints` is the other half of that: a straight line from the kitchen
12	 * to the door cuts diagonally through the middle of the dining room, which
13	 * reads as a token sliding over furniture rather than a person walking. Every
14	 * hop instead steps out to the hallway line (`spineY` from
15	 * `restaurant-arena-layout.ts`), rides it, and turns into the destination room
16	 * — so every segment is axis-aligned and stays in a room or the hallway.
17	 */
18	
19	import type { ArenaLocation, ArenaPoint } from "./restaurant-arena-layout.js";
20	
21	export type WalkNode = ArenaLocation;
22	export type Point = ArenaPoint;
23	
24	/**
25	 * One hallway, both directions. `pass` and `floor` have no shortcut past them:
26	 * they are the only way between the kitchen and the door.
27	 */
28	export const WALK_GRAPH: Record<WalkNode, readonly WalkNode[]> = {
29	  kitchen: ["pass"],
30	  pass: ["kitchen", "floor"],
31	  floor: ["pass", "queue"],
32	  queue: ["floor"],
33	};
34	
35	/** Walking pace. Fast enough to not hold up the shift, slow enough to read. */
36	export const WALK_SPEED_PX_PER_SEC = 200;
37	
38	/**
39	 * The nodes to visit to get from `from` to `to`, inclusive of both ends —
40	 * `bfsPath("kitchen", "queue")` is the full `kitchen → pass → floor → queue`
41	 * route, and `bfsPath(n, n)` is just `[n]`. Returns `[]` only if `to` is
42	 * unreachable, which the graph above never is.
43	 */
44	export function bfsPath(from: WalkNode, to: WalkNode): WalkNode[] {
45	  if (from === to) return [from];
46	  const previous = new Map<WalkNode, WalkNode>();
47	  const seen = new Set<WalkNode>([from]);
48	  const queue: WalkNode[] = [from];
49	
50	  while (queue.length > 0) {
51	    const node = queue.shift()!;
52	    for (const next of WALK_GRAPH[node]) {
53	      if (seen.has(next)) continue;
54	      seen.add(next);
55	      previous.set(next, node);
56	      if (next === to) {
57	        const path: WalkNode[] = [to];
58	        let cursor: WalkNode = to;
59	        while (cursor !== from) {
60	          cursor = previous.get(cursor)!;
61	          path.unshift(cursor);
62	        }
63	        return path;
64	      }
65	      queue.push(next);
66	    }
67	  }
68	  return [];
69	}
70	
71	function samePoint(a: Point, b: Point): boolean {
72	  return Math.abs(a.x - b.x) < 0.5 && Math.abs(a.y - b.y) < 0.5;
73	}
74	
75	/**
76	 * Pixel path from `start`, through `nodes` in order, riding the y=`spineY`
77	 * hallway instead of cutting diagonally through a room.
78	 *
79	 * Each leg is up to three axis-aligned segments: out of the room onto the
80	 * hallway, along the hallway, then into the destination. Segments that would
81	 * be zero-length are dropped, so a walk that is already on the hallway is a
82	 * single straight run.
83	 */
84	export function corridorPoints(
85	  start: Point,
86	  nodes: readonly WalkNode[],
87	  waypoints: Record<WalkNode, Point>,
88	  spineY: number,
89	): Point[] {
90	  const points: Point[] = [];
91	  let cursor: Point = { x: start.x, y: start.y };
92	
93	  const push = (point: Point) => {
94	    if (samePoint(cursor, point)) return;
95	    points.push(point);
96	    cursor = point;
97	  };
98	
99	  for (const node of nodes) {
100	    const slot = waypoints[node];
101	    if (!slot) continue;
102	    if (Math.abs(slot.x - cursor.x) >= 0.5) {
103	      // Sideways travel happens on the hallway, never across a room.
104	      push({ x: cursor.x, y: spineY });
105	      push({ x: slot.x, y: spineY });
106	    }
107	    push({ x: slot.x, y: slot.y });
108	  }
109	  return points;
110	}
111	
112	/** Duration of a single straight hop between two points, at WALK_SPEED_PX_PER_SEC. */
113	export function hopDurationMs(from: Point, to: Point): number {
114	  const distance = Math.hypot(to.x - from.x, to.y - from.y);
115	  return (distance / WALK_SPEED_PX_PER_SEC) * 1000;
116	}
117	
118	/** Ease in and out of each hop, so a turn reads as a step rather than a slide. */
119	function ease(t: number): number {
120	  return t < 0.5 ? 2 * t * t : 1 - 2 * (1 - t) * (1 - t);
121	}
122	
123	/**
124	 * One member of staff, walking.
125	 *
126	 * The scene repaints from scratch constantly, so a walk cannot live in a tween
127	 * on a game object that a repaint is about to destroy — this owns the pixel
128	 * position across repaints and the scene's `update` drives it. `node` is where
129	 * the walker *is* (the last node it reached), not where it is heading, so
130	 * re-targeting mid-walk routes from a real place on the floor.
131	 */
132	export class StaffWalker {
133	  x: number;
134	  y: number;
135	  facing: 1 | -1 = 1;
136	  walking = false;
137	  /** Set while the player has the token under the pointer; `step` stands down. */
138	  dragging = false;
139	  node: WalkNode;
140	
141	  /** Where the current path ends up, once it gets there. */
142	  private destination: WalkNode;
143	  private queue: Point[] = [];
144	  private from: Point;
145	  private to?: Point;
146	  private elapsed = 0;
147	  private duration = 0;
148	
149	  /** `slot` is the pixel position of `node`; the walker starts parked there. */
150	  constructor(node: WalkNode, slot: Point) {
151	    this.node = node;
152	    this.destination = node;
153	    this.x = slot.x;
154	    this.y = slot.y;
155	    this.from = { x: slot.x, y: slot.y };
156	  }
