/**
 * Staff movement across the Restaurant Arena floor.
 *
 * The floor is one hallway, not a set of teleport pads: kitchen — pass — floor
 * — queue, in that order. The pass and the dining room are through-stations, so
 * a cook sent to the door walks out through the pass and across the dining
 * room to get there. That is the whole point of animating the move at all —
 * a token that teleports says nothing, while one that has to cross the room
 * shows the player what an assignment actually costs.
 *
 * `corridorPoints` is the other half of that: a straight line from the kitchen
 * to the door cuts diagonally through the middle of the dining room, which
 * reads as a token sliding over furniture rather than a person walking. Every
 * hop instead steps out to the hallway line (`spineY` from
 * `restaurant-arena-layout.ts`), rides it, and turns into the destination room
 * — so every segment is axis-aligned and stays in a room or the hallway.
 */

import type { ArenaLocation, ArenaPoint } from "./restaurant-arena-layout.js";

export type WalkNode = ArenaLocation;
export type Point = ArenaPoint;

/**
 * One hallway, both directions. `pass` and `floor` have no shortcut past them:
 * they are the only way between the kitchen and the door.
 */
export const WALK_GRAPH: Record<WalkNode, readonly WalkNode[]> = {
  kitchen: ["pass"],
  pass: ["kitchen", "floor"],
  floor: ["pass", "queue"],
  queue: ["floor"],
};

/** Walking pace. Fast enough to not hold up the shift, slow enough to read. */
export const WALK_SPEED_PX_PER_SEC = 200;

/**
 * The nodes to visit to get from `from` to `to`, inclusive of both ends —
 * `bfsPath("kitchen", "queue")` is the full `kitchen → pass → floor → queue`
 * route, and `bfsPath(n, n)` is just `[n]`. Returns `[]` only if `to` is
 * unreachable, which the graph above never is.
 */
export function bfsPath(from: WalkNode, to: WalkNode): WalkNode[] {
  if (from === to) return [from];
  const previous = new Map<WalkNode, WalkNode>();
  const seen = new Set<WalkNode>([from]);
  const queue: WalkNode[] = [from];

  while (queue.length > 0) {
    const node = queue.shift()!;
    for (const next of WALK_GRAPH[node]) {
      if (seen.has(next)) continue;
      seen.add(next);
      previous.set(next, node);
      if (next === to) {
        const path: WalkNode[] = [to];
        let cursor: WalkNode = to;
        while (cursor !== from) {
          cursor = previous.get(cursor)!;
          path.unshift(cursor);
        }
        return path;
      }
      queue.push(next);
    }
  }
  return [];
}

function samePoint(a: Point, b: Point): boolean {
  return Math.abs(a.x - b.x) < 0.5 && Math.abs(a.y - b.y) < 0.5;
}

/**
 * Pixel path from `start`, through `nodes` in order, riding the y=`spineY`
 * hallway instead of cutting diagonally through a room.
 *
 * Each leg is up to three axis-aligned segments: out of the room onto the
 * hallway, along the hallway, then into the destination. Segments that would
 * be zero-length are dropped, so a walk that is already on the hallway is a
 * single straight run.
 */
export function corridorPoints(
  start: Point,
  nodes: readonly WalkNode[],
  waypoints: Record<WalkNode, Point>,
  spineY: number,
): Point[] {
  const points: Point[] = [];
  let cursor: Point = { x: start.x, y: start.y };

  const push = (point: Point) => {
    if (samePoint(cursor, point)) return;
    points.push(point);
    cursor = point;
  };

  for (const node of nodes) {
    const slot = waypoints[node];
    if (!slot) continue;
    if (Math.abs(slot.x - cursor.x) >= 0.5) {
      // Sideways travel happens on the hallway, never across a room.
      push({ x: cursor.x, y: spineY });
      push({ x: slot.x, y: spineY });
    }
    push({ x: slot.x, y: slot.y });
  }
  return points;
}

/** Duration of a single straight hop between two points, at WALK_SPEED_PX_PER_SEC. */
export function hopDurationMs(from: Point, to: Point): number {
  const distance = Math.hypot(to.x - from.x, to.y - from.y);
  return (distance / WALK_SPEED_PX_PER_SEC) * 1000;
}

/** Ease in and out of each hop, so a turn reads as a step rather than a slide. */
function ease(t: number): number {
  return t < 0.5 ? 2 * t * t : 1 - 2 * (1 - t) * (1 - t);
}

/**
 * One member of staff, walking.
 *
 * The scene repaints from scratch constantly, so a walk cannot live in a tween
 * on a game object that a repaint is about to destroy — this owns the pixel
 * position across repaints and the scene's `update` drives it. `node` is where
 * the walker *is* (the last node it reached), not where it is heading, so
 * re-targeting mid-walk routes from a real place on the floor.
 */
export class StaffWalker {
  x: number;
  y: number;
  facing: 1 | -1 = 1;
  walking = false;
  /** Set while the player has the token under the pointer; `step` stands down. */
  dragging = false;
  node: WalkNode;

  /** Where the current path ends up, once it gets there. */
  private destination: WalkNode;
  private queue: Point[] = [];
  private from: Point;
  private to?: Point;
  private elapsed = 0;
  private duration = 0;

  /** `slot` is the pixel position of `node`; the walker starts parked there. */
  constructor(node: WalkNode, slot: Point) {
    this.node = node;
    this.destination = node;
    this.x = slot.x;
    this.y = slot.y;
    this.from = { x: slot.x, y: slot.y };
  }

  /** Teleport onto `slot`/`node` with no walk in progress (e.g. after a drag drop). */
  snap(slot: Point, node: WalkNode): void {
    this.x = slot.x;
    this.y = slot.y;
    this.node = node;
    this.destination = node;
    this.from = { x: slot.x, y: slot.y };
    this.to = undefined;
    this.queue = [];
    this.elapsed = 0;
    this.duration = 0;
    this.walking = false;
  }

  /** Walk toward `target` from the current pixel, along the hallway at `spineY`. */
  setTarget(target: WalkNode, waypoints: Record<WalkNode, Point>, spineY: number): void {
    const nodes = bfsPath(this.node, target);
    this.queue = corridorPoints({ x: this.x, y: this.y }, nodes, waypoints, spineY);
    this.destination = nodes.length > 0 ? target : this.node;
    this.to = undefined;
    this.walking = this.queue.length > 0;
    if (!this.walking) {
      this.node = this.destination;
      return;
    }
    this.beginHop();
  }

  /**
   * Advance the walk by `dtMs` at simulation `speed` (0 pauses). Returns
   * whether the pixel position changed.
   */
  step(dtMs: number, speed: number): boolean {
    if (this.dragging || !this.walking || speed <= 0 || dtMs <= 0) return false;
    const startX = this.x;
    const startY = this.y;
    let budget = dtMs * speed;

    while (budget > 0 && this.to) {
      const remaining = this.duration - this.elapsed;
      if (budget < remaining) {
        this.elapsed += budget;
        budget = 0;
      } else {
        budget -= Math.max(0, remaining);
        this.elapsed = this.duration;
      }
      this.applyHop();
      if (this.elapsed >= this.duration) this.beginHop();
    }

    return this.x !== startX || this.y !== startY;
  }

  private beginHop(): void {
    const next = this.queue.shift();
    if (!next) {
      this.to = undefined;
      this.walking = false;
      this.node = this.destination;
      return;
    }
    this.from = { x: this.x, y: this.y };
    this.to = next;
    this.elapsed = 0;
    this.duration = hopDurationMs(this.from, next);
    if (next.x > this.from.x) this.facing = 1;
    else if (next.x < this.from.x) this.facing = -1;
  }

  private applyHop(): void {
    const to = this.to;
    if (!to) return;
    const t = this.duration > 0 ? ease(Math.min(1, this.elapsed / this.duration)) : 1;
    this.x = this.from.x + (to.x - this.from.x) * t;
    this.y = this.from.y + (to.y - this.from.y) * t;
  }
}

