128	 * position across repaints and the scene's `update` drives it. `node` is where
129	 * the walker *is* (the last node it reached), not where it is heading, so
130	 * re-targeting mid-walk routes from a real place on the floor.
131	 */
132	export class StaffWalker {
133	  x: number;
134	  y: number;
135	  facing: 1 | -1 = 1;
136	  walking = false;
137	  /** Set while the player has the token under the pointer; `step` stands down. */
138	  dragging = false;
139	  node: WalkNode;
140	
141	  /** Where the current path ends up, once it gets there. */
142	  private destination: WalkNode;
143	  private queue: Point[] = [];
144	  private from: Point;
145	  private to?: Point;
146	  private elapsed = 0;
147	  private duration = 0;
148	
149	  /** `slot` is the pixel position of `node`; the walker starts parked there. */
150	  constructor(node: WalkNode, slot: Point) {
151	    this.node = node;
152	    this.destination = node;
153	    this.x = slot.x;
154	    this.y = slot.y;
155	    this.from = { x: slot.x, y: slot.y };
156	  }
157	
158	  /** Teleport onto `slot`/`node` with no walk in progress (e.g. after a drag drop). */
159	  snap(slot: Point, node: WalkNode): void {
160	    this.x = slot.x;
161	    this.y = slot.y;
162	    this.node = node;
163	    this.destination = node;
164	    this.from = { x: slot.x, y: slot.y };
165	    this.to = undefined;
166	    this.queue = [];
167	    this.elapsed = 0;
168	    this.duration = 0;
169	    this.walking = false;
170	  }
171	
172	  /** Walk toward `target` from the current pixel, along the hallway at `spineY`. */
173	  setTarget(target: WalkNode, waypoints: Record<WalkNode, Point>, spineY: number): void {
174	    const nodes = bfsPath(this.node, target);
175	    this.queue = corridorPoints({ x: this.x, y: this.y }, nodes, waypoints, spineY);
176	    this.destination = nodes.length > 0 ? target : this.node;
177	    this.to = undefined;
178	    this.walking = this.queue.length > 0;
179	    if (!this.walking) {
180	      this.node = this.destination;
181	      return;
182	    }
183	    this.beginHop();
184	  }
185	
186	  /**
187	   * Advance the walk by `dtMs` at simulation `speed` (0 pauses). Returns
188	   * whether the pixel position changed.
189	   */
190	  step(dtMs: number, speed: number): boolean {
191	    if (this.dragging || !this.walking || speed <= 0 || dtMs <= 0) return false;
192	    const startX = this.x;
193	    const startY = this.y;
194	    let budget = dtMs * speed;
195	
196	    while (budget > 0 && this.to) {
197	      const remaining = this.duration - this.elapsed;
198	      if (budget < remaining) {
199	        this.elapsed += budget;
200	        budget = 0;
201	      } else {
202	        budget -= Math.max(0, remaining);
203	        this.elapsed = this.duration;
204	      }
205	      this.applyHop();
206	      if (this.elapsed >= this.duration) this.beginHop();
207	    }
208	
209	    return this.x !== startX || this.y !== startY;
210	  }
211	
212	  private beginHop(): void {
213	    const next = this.queue.shift();
214	    if (!next) {
215	      this.to = undefined;
216	      this.walking = false;
217	      this.node = this.destination;
218	      return;
219	    }
220	    this.from = { x: this.x, y: this.y };
221	    this.to = next;
222	    this.elapsed = 0;
223	    this.duration = hopDurationMs(this.from, next);
224	    if (next.x > this.from.x) this.facing = 1;
225	    else if (next.x < this.from.x) this.facing = -1;
226	  }
227	
228	  private applyHop(): void {
229	    const to = this.to;
230	    if (!to) return;
231	    const t = this.duration > 0 ? ease(Math.min(1, this.elapsed / this.duration)) : 1;
232	    this.x = this.from.x + (to.x - this.from.x) * t;
233	    this.y = this.from.y + (to.y - this.from.y) * t;
234	  }
235	}
