bun -e '
// Contract check: every name and signature the doc pins down, exercised the way
// a caller would, straight off the built modules.
const layoutMod = await import("./overlay/restaurant-arena-layout.ts");
const walkMod = await import("./overlay/staff-walk.ts");
const gateMod = await import("./overlay/restaurant-arena-repaint-gate.ts");

const l = layoutMod.restaurantArenaLayout(520, 740);
const fields = ["compact","scale","feedBeside","topBar","brief","kitchen","pass","dining","door","doorStand","waypoints","spineY","tickets","feed"];
const missing = fields.filter((f) => !(f in l));
console.log("layout missing:", missing);
console.log("waypoint nodes:", Object.keys(l.waypoints));

console.log("WALK_GRAPH:", JSON.stringify(walkMod.WALK_GRAPH));
console.log("WALK_SPEED:", walkMod.WALK_SPEED_PX_PER_SEC);
console.log("bfs k->q:", walkMod.bfsPath("kitchen","queue"));
console.log("corridor:", walkMod.corridorPoints(l.waypoints.kitchen, walkMod.bfsPath("kitchen","queue"), l.waypoints, l.spineY));
console.log("hop:", walkMod.hopDurationMs({x:0,y:0},{x:200,y:0}));
const w = new walkMod.StaffWalker("kitchen", l.waypoints.kitchen);
w.setTarget("queue", l.waypoints, l.spineY);
let frames = 0;
while (w.walking && frames < 2000) { w.step(16, 1); frames++; }
console.log("walked in frames:", frames, "at", Math.round(w.x), Math.round(w.y), "node", w.node, "facing", w.facing);
w.snap({x: 1, y: 2}, "floor");
console.log("after snap:", w.x, w.y, w.node, w.walking);

const gate = new gateMod.RepaintGate();
console.log("paint now:", gate.requestPaint(), "isDragging:", gate.isDragging);
gate.beginDrag();
console.log("held:", gate.requestPaint(), gate.requestPaint(), "isDragging:", gate.isDragging);
console.log("owed at drop:", gate.endDrag());
gate.beginDrag(); gate.resize();
console.log("after resize owes:", gate.endDrag(), "isDragging:", gate.isDragging);
'

