    const walker = new StaffWalker("queue", waypoints.queue);
    walker.setTarget("kitchen", waypoints, spineY);
    runToRest(walker);
    // The kitchen is stage left of the door.
    expect(walker.facing).toBe(-1);
    // Turning back: the first hop out to the hallway is straight up, so the
    // turn happens on the hop that actually travels sideways.
    walker.setTarget("queue", waypoints, spineY);
    let turned = false;
    while (walker.walking && !turned) {
      walker.step(16, 1);
      turned = walker.facing === 1;
    }
