function samePoint(a: Point, b: Point): boolean {
  return Math.abs(a.x - b.x) < 0.5 && Math.abs(a.y - b.y) < 0.5;
}

/** Is `value` on the stretch of hallway between `a` and `b`? */
function betweenX(value: number, a: number, b: number): boolean {
  return value >= Math.min(a, b) - 0.5 && value <= Math.max(a, b) + 0.5;
}

/**
 * Pixel path from `start`, through `nodes` in order, riding the y=`spineY`
 * hallway instead of cutting diagonally through a room.
 *
 * Each leg is up to three axis-aligned segments: out of the room onto the
 * hallway, along the hallway, then into the destination. Segments that would
 * be zero-length are dropped, so a walk that is already on the hallway is a
 * single straight run.
 *
 * Only the last node is somewhere the walker *stops*. The through-stations in
 * between are walked through — they bend the hallway ride when they sit
 * between here and there, and are otherwise left alone. Sending everyone via
 * the exact centre of every room they cross would have a cook heading for the
 * door march into the middle of the dining room and then double back to the
 * host stand, which reads as a mistake rather than as a walk.
 */
export function corridorPoints(
  start: Point,
  nodes: readonly WalkNode[],
  waypoints: Record<WalkNode, Point>,
  spineY: number,
): Point[] {
  const points: Point[] = [];
  let cursor: Point = { x: start.x, y: start.y };

  const push = (point: Point) => {
    if (samePoint(cursor, point)) return;
    points.push(point);
    cursor = point;
  };

  const last = nodes.length > 0 ? nodes[nodes.length - 1] : undefined;
  const finish = last === undefined ? undefined : waypoints[last];
  if (!finish) return points;

  // Nobody changes room, so nobody needs the hallway: crossing to the far side
  // of the room you are already standing in is two sides of a right angle.
  if (nodes.length < 2) {
    push({ x: finish.x, y: cursor.y });
    push({ x: finish.x, y: finish.y });
    return points;
  }

  for (const node of nodes) {
    const slot = waypoints[node];
    if (!slot) continue;
    const arriving = node === last;
    if (!arriving && !betweenX(slot.x, cursor.x, finish.x)) continue;
    if (Math.abs(slot.x - cursor.x) >= 0.5) {
      // Sideways travel happens on the hallway, never across a room.
      push({ x: cursor.x, y: spineY });
      push({ x: slot.x, y: spineY });
    }
    if (arriving) push({ x: slot.x, y: slot.y });
  }
  return points;
}

