arguments.new_string:
  test("has nothing to walk when it is already there", () => {
    expect(corridorPoints(waypoints.pass, ["pass"], waypoints, spineY)).toEqual([]);
  });

  test("never doubles back down the hallway it just came up", () => {
    // The through-stations are crossed, not visited: routing via the centre of
    // the dining room would send a cook heading for the host stand past it and
    // then back, since the stand sits left of that centre.
    for (const from of Object.keys(waypoints) as WalkNode[]) {
      for (const to of Object.keys(waypoints) as WalkNode[]) {
        const points = corridorPoints(waypoints[from], bfsPath(from, to), waypoints, spineY);
        let previous = waypoints[from];
        let direction = 0;
        for (const point of points) {
          const step = point.x - previous.x;
          if (Math.abs(step) >= 0.5) {
            const sign = Math.sign(step);
            expect(direction === 0 || direction === sign).toBe(true);
            direction = sign;
          }
          previous = point;
        }
      }
    }
  });

  test("crossing the room you are standing in does not go via the hallway", () => {
    // Where a drag drop lands: same zone, wrong spot. Walking up to the
    // hallway and back down to get two feet sideways would look ridiculous.
    const dropped = { x: waypoints.queue.x + 60, y: waypoints.queue.y + 9 };
    const points = corridorPoints(dropped, ["queue"], waypoints, spineY);
    expect(points.length).toBeGreaterThan(0);
    for (const point of points) {
      expect(Math.abs(point.y - spineY)).toBeGreaterThan(1);
    }
    expect(points[points.length - 1]).toEqual(waypoints.queue);
  });
});

