1	/**
2	 * Where everything on the Restaurant Arena floor goes, for a canvas of any
3	 * size.
4	 *
5	 * The scene itself is authored in CSS-pixel units and repaints from scratch on
6	 * every state change (see `restaurant-arena-scene.ts`), so the whole layout is
7	 * a pure function of the canvas box: one call per paint, no retained state.
8	 * Keeping it out of the scene is what makes the sizing behaviour — the
9	 * responsive band-squeeze below, the compact break, the `scale` ramp — testable
10	 * without booting Phaser.
11	 *
12	 * Two things this file is responsible for beyond "which rectangle goes where":
13	 *
14	 *  - `scale`. A window twice the baseline size drawn with baseline-sized type
15	 *    reads as a big empty room with unreadable labels in it. Every font size
16	 *    and figure in the scene is multiplied by this, so text grows with the
17	 *    window instead of staying pinned to a 520×740 design. It never goes below
18	 *    1: shrinking type is how you make a small window illegible, so a small
19	 *    window gets the compact layout instead (fewer/tighter bands, same
20	 *    readable type).
21	 *  - `spineY`. The hallway. Staff walking between rooms ride this line rather
22	 *    than cutting diagonally across the dining room (see `staff-walk.ts`), so
23	 *    it has to be a y that is inside the kitchen, the pass *and* the dining
24	 *    room — the three rooms the corridor connects.
25	 */
26	
27	export type ArenaRect = { x: number; y: number; width: number; height: number };
28	export type ArenaPoint = { x: number; y: number };
29	export type ArenaLocation = "floor" | "kitchen" | "pass" | "queue";
30	
31	export interface RestaurantArenaLayout {
32	  compact: boolean;
33	  scale: number;
34	  feedBeside: boolean;
35	  topBar: ArenaRect;
36	  brief: ArenaRect;
37	  kitchen: ArenaRect;
38	  pass: ArenaRect;
39	  dining: ArenaRect;
40	  door: ArenaRect;
41	  doorStand: ArenaRect;
42	  waypoints: Record<ArenaLocation, ArenaPoint>;
43	  /** Y coordinate of the hallway line that runs through the pass zone. */
44	  spineY: number;
45	  tickets: ArenaRect;
46	  feed: ArenaRect;
47	}
48	
49	/** The window this scene was designed against: `scale` is exactly 1 here. */
50	export const BASELINE_WIDTH = 520;
51	export const BASELINE_HEIGHT = 740;
52	/**
53	 * Past roughly 1.9× the design size the room is big enough that growing the
54	 * type further just wastes the space it was supposed to fill.
55	 */
56	export const MAX_SCALE = 1.9;
57	/** Under this, bands tighten and the growing-text ramp is switched off. */
58	export const COMPACT_WIDTH = 460;
59	export const COMPACT_HEIGHT = 420;
60	/** The feed only earns a side rail once the floor can spare the width. */
61	export const FEED_BESIDE_WIDTH = 600;
62	
63	/** The host stand is a thing you aim a drag at, so it has a floor size. */
64	export const MIN_DOOR_STAND_WIDTH = 56;
65	export const MIN_DOOR_STAND_HEIGHT = 22;
66	
67	function clamp(value: number, min: number, max: number): number {
68	  return Math.min(Math.max(value, min), max);
69	}
70	
71	function center(rect: ArenaRect): ArenaPoint {
72	  return { x: Math.round(rect.x + rect.width / 2), y: Math.round(rect.y + rect.height / 2) };
73	}
74	
75	/**
76	 * How much bigger than the baseline this window is, in the *tighter* of the two
77	 * axes — a window that is wide but short has no more room for tall type than a
78	 * short one, so the smaller ratio wins.
79	 */
80	export function arenaScale(width: number, height: number): number {
81	  if (width < COMPACT_WIDTH || height < COMPACT_HEIGHT) return 1;
82	  const ratio = Math.min(width / BASELINE_WIDTH, height / BASELINE_HEIGHT);
83	  return clamp(ratio, 1, MAX_SCALE);
84	}
85	
86	export function restaurantArenaLayout(width: number, height: number): RestaurantArenaLayout {
87	  const w = Math.max(0, Math.round(width));
88	  const h = Math.max(0, Math.round(height));
89	  const compact = w < COMPACT_WIDTH || h < COMPACT_HEIGHT;
90	  const scale = arenaScale(w, h);
91	  const feedBeside = w >= FEED_BESIDE_WIDTH;
92	  /** A baseline design length, at this window's size. */
93	  const unit = (px: number) => Math.round(px * scale);
94	
95	  const margin = Math.min(compact ? 6 : unit(8), Math.floor(Math.min(w, h) / 20));
96	  const contentWidth = Math.max(0, w - margin * 2);
97	  const innerHeight = Math.max(0, h - margin * 2);
98	  // Gaps are capped against the box as well, so a silly-small canvas spends
99	  // its pixels on rooms rather than on the spaces between them.
100	  const gapX = Math.min(compact ? 4 : unit(6), Math.floor(contentWidth / 6));
101	  const gapY = Math.min(compact ? 4 : unit(6), Math.floor(innerHeight / 12));
102	
103	  // ── Vertical bands ────────────────────────────────────────────────────
104	  // topBar / brief / floor / tickets, plus the feed as a fourth band when it
105	  // isn't beside the floor. The floor gets whatever is left; if that would
106	  // leave it unusably short, the fixed bands are squeezed proportionally
107	  // instead of the floor going negative and spilling out of the canvas.
108	  const bandGaps = gapY * (feedBeside ? 3 : 4);
109	  const room = Math.max(0, innerHeight - bandGaps);
110	  const wanted = {
111	    topBar: compact ? 32 : unit(38),
112	    brief: compact ? 28 : unit(32),
113	    tickets: compact ? 60 : unit(72),
114	    feed: feedBeside ? 0 : Math.max(compact ? 90 : unit(110), Math.round(h * 0.2)),
115	  };
116	  const wantedSum = wanted.topBar + wanted.brief + wanted.tickets + wanted.feed;
117	  const floorWanted = compact ? 90 : unit(120);
118	  let squeeze = 1;
119	  let floorHeight = room - wantedSum;
120	  if (floorHeight < floorWanted) {
121	    // The floor is the game; it keeps 40% of the body no matter how cramped
122	    // the window is, and the chrome around it gives up the difference.
123	    floorHeight = Math.min(floorWanted, Math.round(room * 0.4));
124	    squeeze = wantedSum > 0 ? Math.max(0, room - floorHeight) / wantedSum : 0;
125	  }
126	  const topBarHeight = Math.floor(wanted.topBar * squeeze);
127	  const briefHeight = Math.floor(wanted.brief * squeeze);
128	  const ticketsHeight = Math.floor(wanted.tickets * squeeze);
129	  const feedHeight = Math.floor(wanted.feed * squeeze);
130	
131	  const briefY = margin + topBarHeight + gapY;
132	  const bodyY = briefY + briefHeight + gapY;
133	
134	  // ── The floor column, and the feed's side rail ────────────────────────
135	  const feedWidth = feedBeside
136	    ? clamp(Math.round(contentWidth * 0.26), Math.min(unit(200), Math.round(contentWidth * 0.42)), Math.round(contentWidth * 0.42))
137	    : 0;
138	  const columnWidth = feedBeside ? Math.max(0, contentWidth - feedWidth - gapX) : contentWidth;
139	
140	  // kitchen | pass | dining, left to right, with the two gaps taken out of
141	  // the row up front so the three rooms always add back up to the column.
142	  const rowWidth = Math.max(0, columnWidth - gapX * 2);
143	  const kitchenWidth = Math.round(rowWidth * 0.25);
144	  const passWidth = clamp(Math.max(unit(24), Math.round(rowWidth * 0.075)), 0, Math.round(rowWidth * 0.2));
145	  const diningWidth = Math.max(0, rowWidth - kitchenWidth - passWidth);
146	
147	  const doorHeight = clamp(
148	    Math.max(unit(56), Math.round(floorHeight * 0.32)),
149	    0,
150	    Math.max(0, floorHeight - gapY - Math.min(unit(60), Math.round(floorHeight * 0.3))),
151	  );
152	  const diningHeight = Math.max(0, floorHeight - doorHeight - gapY);
153	
154	  const kitchen: ArenaRect = { x: margin, y: bodyY, width: kitchenWidth, height: floorHeight };
155	  const pass: ArenaRect = { x: kitchen.x + kitchenWidth + gapX, y: bodyY, width: passWidth, height: floorHeight };
156	  const diningX = pass.x + passWidth + gapX;
157	  const dining: ArenaRect = { x: diningX, y: bodyY, width: diningWidth, height: diningHeight };
158	  const door: ArenaRect = {
159	    x: diningX,
160	    y: bodyY + diningHeight + gapY,
161	    width: diningWidth,
162	    height: doorHeight,
163	  };
164	
165	  // The host stand. It is a drop target for a dragged host as much as it is a
166	  // panel, so it keeps a usable size even when the door band is tiny — and is
167	  // then clamped into the canvas rather than into the door.
168	  const labelHeight = unit(14);
169	  const standWidth = Math.max(MIN_DOOR_STAND_WIDTH, Math.min(unit(90), Math.round(door.width * 0.36)));
170	  const standHeight = Math.max(MIN_DOOR_STAND_HEIGHT, Math.min(unit(36), door.height - labelHeight - 4));
171	  const hostGutter = Math.min(unit(40), Math.max(0, door.width - standWidth - 4));
172	  const doorStand: ArenaRect = {
173	    x: clamp(door.x + hostGutter, 0, Math.max(0, w - standWidth)),
174	    y: clamp(door.y + labelHeight, 0, Math.max(0, h - standHeight)),
175	    width: standWidth,
176	    height: standHeight,
177	  };
178	
179	  // The hallway. Lands inside the dining room, the pass and the kitchen at
180	  // once, which is what lets a walk between any two of them ride it.
181	  const spineY = Math.round(dining.y + dining.height / 2);
182	
183	  const waypoints: Record<ArenaLocation, ArenaPoint> = {
184	    kitchen: center(kitchen),
185	    pass: center(pass),
186	    floor: center(dining),
187	    queue: center(doorStand),
188	  };
189	
190	  const tickets: ArenaRect = {
191	    x: margin,
192	    y: bodyY + floorHeight + gapY,
193	    width: columnWidth,
194	    height: ticketsHeight,
195	  };
196	  const feed: ArenaRect = feedBeside
197	    ? {
198	        x: margin + columnWidth + gapX,
199	        y: bodyY,
200	        width: feedWidth,
201	        height: floorHeight + gapY + ticketsHeight,
202	      }
203	    : {
204	        x: margin,
205	        y: tickets.y + ticketsHeight + gapY,
206	        width: contentWidth,
207	        height: feedHeight,
208	      };
209	
210	  return {
211	    compact,
212	    scale,
213	    feedBeside,
214	    topBar: { x: margin, y: margin, width: contentWidth, height: topBarHeight },
215	    brief: { x: margin, y: briefY, width: contentWidth, height: briefHeight },
216	    kitchen,
217	    pass,
218	    dining,
219	    door,
220	    doorStand,
221	    waypoints,
222	    spineY,
223	    tickets,
224	    feed,
225	  };
226	}
