124	    squeeze = wantedSum > 0 ? Math.max(0, room - floorHeight) / wantedSum : 0;
125	  }
126	  const topBarHeight = Math.floor(wanted.topBar * squeeze);
127	  const briefHeight = Math.floor(wanted.brief * squeeze);
128	  const ticketsHeight = Math.floor(wanted.tickets * squeeze);
129	  const feedHeight = Math.floor(wanted.feed * squeeze);
130	
131	  const briefY = margin + topBarHeight + gapY;
132	  const bodyY = briefY + briefHeight + gapY;
133	
134	  // ── The floor column, and the feed's side rail ────────────────────────
135	  const feedWidth = feedBeside
136	    ? clamp(Math.round(contentWidth * 0.26), Math.min(unit(200), Math.round(contentWidth * 0.42)), Math.round(contentWidth * 0.42))
137	    : 0;
138	  const columnWidth = feedBeside ? Math.max(0, contentWidth - feedWidth - gapX) : contentWidth;
139	
140	  // kitchen | pass | dining, left to right, with the two gaps taken out of
141	  // the row up front so the three rooms always add back up to the column.
142	  const rowWidth = Math.max(0, columnWidth - gapX * 2);
143	  const kitchenWidth = Math.round(rowWidth * 0.25);
144	  const passWidth = clamp(Math.max(unit(24), Math.round(rowWidth * 0.075)), 0, Math.round(rowWidth * 0.2));
145	  const diningWidth = Math.max(0, rowWidth - kitchenWidth - passWidth);
146	
147	  const doorHeight = clamp(
148	    Math.max(unit(56), Math.round(floorHeight * 0.32)),
149	    0,
150	    Math.max(0, floorHeight - gapY - Math.min(unit(60), Math.round(floorHeight * 0.3))),
151	  );
152	  const diningHeight = Math.max(0, floorHeight - doorHeight - gapY);
153	
154	  const kitchen: ArenaRect = { x: margin, y: bodyY, width: kitchenWidth, height: floorHeight };
155	  const pass: ArenaRect = { x: kitchen.x + kitchenWidth + gapX, y: bodyY, width: passWidth, height: floorHeight };
156	  const diningX = pass.x + passWidth + gapX;
157	  const dining: ArenaRect = { x: diningX, y: bodyY, width: diningWidth, height: diningHeight };
158	  const door: ArenaRect = {
159	    x: diningX,
160	    y: bodyY + diningHeight + gapY,
161	    width: diningWidth,
162	    height: doorHeight,
163	  };
164	
165	  // The host stand. It is a drop target for a dragged host as much as it is a
166	  // panel, so it keeps a usable size even when the door band is tiny — and is
167	  // then clamped into the canvas rather than into the door.
168	  const labelHeight = unit(14);
169	  const standWidth = Math.max(MIN_DOOR_STAND_WIDTH, Math.min(unit(90), Math.round(door.width * 0.36)));
170	  const standHeight = Math.max(MIN_DOOR_STAND_HEIGHT, Math.min(unit(36), door.height - labelHeight - 4));
171	  const hostGutter = Math.min(unit(40), Math.max(0, door.width - standWidth - 4));
172	  const doorStand: ArenaRect = {
173	    x: clamp(door.x + hostGutter, 0, Math.max(0, w - standWidth)),
174	    y: clamp(door.y + labelHeight, 0, Math.max(0, h - standHeight)),
175	    width: standWidth,
176	    height: standHeight,
177	  };
178	
179	  // The hallway. Lands inside the dining room, the pass and the kitchen at
180	  // once, which is what lets a walk between any two of them ride it.
181	  const spineY = Math.round(dining.y + dining.height / 2);
182	
183	  const waypoints: Record<ArenaLocation, ArenaPoint> = {
184	    kitchen: center(kitchen),
185	    pass: center(pass),
186	    floor: center(dining),
187	    queue: center(doorStand),
188	  };
189	
190	  const tickets: ArenaRect = {
191	    x: margin,
192	    y: bodyY + floorHeight + gapY,
193	    width: columnWidth,
194	    height: ticketsHeight,
195	  };
196	  const feed: ArenaRect = feedBeside
197	    ? {
198	        x: margin + columnWidth + gapX,
199	        y: bodyY,
200	        width: feedWidth,
201	        height: floorHeight + gapY + ticketsHeight,
202	      }
203	    : {
204	        x: margin,
205	        y: tickets.y + ticketsHeight + gapY,
206	        width: contentWidth,
207	        height: feedHeight,
208	      };
209	
210	  return {
211	    compact,
212	    scale,
213	    feedBeside,
214	    topBar: { x: margin, y: margin, width: contentWidth, height: topBarHeight },
215	    brief: { x: margin, y: briefY, width: contentWidth, height: briefHeight },
216	    kitchen,
217	    pass,
218	    dining,
219	    door,
220	    doorStand,
221	    waypoints,
222	    spineY,
223	    tickets,
224	    feed,
225	  };
226	}
