/**
 * Holds a repaint back while the player is dragging.
 *
 * `RestaurantArenaScene` repaints by destroying every game object and building
 * new ones (`children.removeAll(true)`), which is fine sixty times a second
 * until the object being destroyed is the one under the player's finger: the
 * token vanishes mid-drag, Phaser's drag ends on an object that no longer
 * exists, and the drop is lost. Ticks arrive on their own clock, so this is not
 * a rare race — dragging a cook across the floor takes about a second, and the
 * shift will tick at least once in it.
 *
 * So a paint requested during a drag is not dropped and not applied: it is
 * *owed*. One repaint, however many were asked for, replayed the moment the
 * drag is over — the token stays under the finger, and the floor is correct
 * again as soon as letting go makes that safe.
 *
 * A resize is the exception. It repaints the whole canvas from scratch (in this
 * scene, by booting a fresh game at the new size), so an owed paint is already
 * satisfied by definition, and any drag it interrupted is over — its token no
 * longer exists and its drop coordinates mean nothing against the new layout.
 * Anything owed is therefore cleared rather than replayed, and a `dragend` that
 * straggles in afterwards owes nothing.
 */
export class RepaintGate {
  private dragging = false;
  private owed = false;

  /** True while a drag is open (between beginDrag() and endDrag()/resize()). */
  get isDragging(): boolean {
    return this.dragging;
  }

  beginDrag(): void {
    this.dragging = true;
  }

  /**
   * Paints immediately (returns true) unless a drag is open, in which case the
   * paint is held back (returns false) and one repaint becomes owed.
   */
  requestPaint(): boolean {
    if (!this.dragging) return true;
    this.owed = true;
    return false;
  }

  /**
   * Ends the drag. Returns whether a repaint was held back during it (and thus
   * needs to be replayed by the caller now).
   */
  endDrag(): boolean {
    this.dragging = false;
    const owed = this.owed;
    this.owed = false;
    return owed;
  }

  /**
   * Drops any open drag and clears anything owed, since the resize itself
   * repaints from scratch.
   */
  resize(): void {
    this.dragging = false;
    this.owed = false;
  }
}

